<template>
  <!-- Chips only — the canvasser identity and hours live in the details card below. -->
  <div class="flex flex-wrap items-center gap-4" data-testid="workshift-review-summary">
    <div class="flex flex-wrap items-center gap-1.5">
      <span :class="['rounded-full px-2.5 py-0.5 text-xs font-semibold uppercase', risk.badgeClass]">
        {{ risk.label }}
      </span>
      <span
        v-for="key in flagKeys"
        :key="key"
        class="inline-flex items-center gap-1 rounded-md px-2 py-1 text-xs font-medium"
        :class="[REVIEW_FLAG_CONFIG[key].accentBg, REVIEW_FLAG_CONFIG[key].accentText]"
      >
        <component :is="REVIEW_FLAG_CONFIG[key].icon" class="size-3.5" />
        {{ REVIEW_FLAG_CONFIG[key].label }}
      </span>
      <!-- Shift-condition chips (former details "Extra info") — shown only when noteworthy. -->
      <span v-for="chip in conditionChips" :key="chip.label" :class="CONDITION_CHIP_CLASS">
        <component :is="chip.icon" class="size-3.5" />
        {{ chip.label }}
      </span>
    </div>
  </div>
</template>

<script setup lang="ts">
import { AlarmClockIcon, CircleAlertIcon, TimerOffIcon } from 'lucide-vue-next';

import type { ReviewFlagKey, RiskLevel } from '~/client';
import { getRiskLevel } from '~/constants/workshifts/canvassingAppStatsConfig';
import { REVIEW_FLAG_CONFIG } from '~/constants/workshifts/reviewConfig';

interface Props {
  riskLevel: RiskLevel | null;
  flagKeys: ReviewFlagKey[];
  lateStart?: boolean;
  isTimeouted?: boolean;
  dataComplete?: boolean | null;
}

const props = defineProps<Props>();

const risk = computed(() => getRiskLevel(props.riskLevel ?? 'none'));

const CONDITION_CHIP_CLASS =
  'inline-flex items-center gap-1 rounded-md bg-amber-100 px-2 py-1 text-xs font-medium text-amber-900';

const conditionChips = computed(() => {
  const chips = [];
  if (props.lateStart) chips.push({ label: 'Late Start', icon: AlarmClockIcon });
  if (props.isTimeouted) chips.push({ label: 'Timed Out', icon: TimerOffIcon });
  if (props.dataComplete === false) chips.push({ label: 'Incomplete Data', icon: CircleAlertIcon });
  return chips;
});
</script>
