<template>
  <Card data-testid="workshift-review-coaching">
    <CardHeader class="pb-2">
      <button
        type="button"
        class="flex w-full items-center justify-between gap-2 text-left"
        :aria-expanded="open"
        @click="open = !open"
      >
        <CardTitle class="flex items-center gap-2 text-sm">
          <MessageSquareIcon class="size-4" /> Coaching Feedback
        </CardTitle>
        <ChevronRightIcon
          class="size-4 shrink-0 text-muted-foreground transition-transform"
          :class="open ? 'rotate-90' : ''"
        />
      </button>
    </CardHeader>
    <CardContent v-if="open" class="flex max-h-96 flex-col gap-3 overflow-y-auto">
      <AppLoader v-if="isLoading" variant="inline" subject="coaching feedback" />
      <AppEmpty v-else-if="!feedback" subject="coaching feedback" variant="table" />
      <template v-else>
        <!-- KPI sections the coach was generated from -->
        <div v-if="sections.length" class="flex flex-col gap-1.5">
          <button
            v-for="section in sections"
            :key="section.key"
            type="button"
            class="rounded-md border px-2.5 py-1.5 text-left transition-colors hover:bg-muted/50"
            @click="toggleSection(section.key)"
          >
            <span class="flex items-center gap-2">
              <Badge :variant="coachingSeverityVariant(section.severity)" size="sm">
                {{ snakeCaseToCapitalizedCase(section.severity) }}
              </Badge>
              <span class="text-xs font-semibold">{{ section.title }}</span>
            </span>
            <span v-if="openSections.has(section.key)" class="mt-1 block text-xs text-muted-foreground">
              {{ section.summary }}
            </span>
          </button>
        </div>
        <!-- The message sent to the canvasser -->
        <div class="whitespace-pre-line rounded-md bg-muted/40 p-3 text-sm leading-6 text-muted-foreground">
          {{ feedback.message }}
        </div>
      </template>
    </CardContent>
  </Card>
</template>

<script setup lang="ts">
import { ChevronRightIcon, MessageSquareIcon } from 'lucide-vue-next';

import type { BadgeVariants } from '~/components/ui/badge';
import type { CoachingSection, CoachingSeverity, GetCoachingFeedbackDetailsResponse } from '~/client';

interface Props {
  feedback: GetCoachingFeedbackDetailsResponse | null;
  isLoading: boolean;
}

const props = defineProps<Props>();

const open = ref(true);

// KPI-section expansion — local only, reset is not needed here since the card
// is re-mounted per work shift (keyed by the page's shift id), same pattern as
// WorkshiftReviewFlagSections's `openSections`.
const openSections = ref(new Set<string>());
function toggleSection(key: string): void {
  const next = new Set(openSections.value);
  if (next.has(key)) next.delete(key);
  else next.add(key);
  openSections.value = next;
}

// `context` is a discriminated union on `context_type`; only the shapes built
// from KPI/conversation components (workshift-end, scheduled-review) carry
// `sections` — critical-threshold context carries `violations` instead. This
// card only ever mounts for workshift-end-triggered feedback in practice, but
// the `in` narrowing degrades gracefully for any context shape instead of
// assuming a specific context_type.
const sections = computed<CoachingSection[]>(() => {
  const context = props.feedback?.context;
  if (!context) return [];
  return 'sections' in context ? context.sections : [];
});

function coachingSeverityVariant(severity: CoachingSeverity): BadgeVariants {
  if (severity === 'critical') return 'destructive';
  if (severity === 'needs_improvement') return 'warning';
  if (severity === 'ok') return 'success';
  return 'info';
}
</script>
