<template>
  <Card data-testid="workshift-review-conversations">
    <CardHeader class="pb-2">
      <div class="flex flex-wrap items-center justify-between gap-2">
        <CardTitle class="flex items-center gap-2 text-sm">
          <MessageSquareIcon class="size-4" /> Voter Conversations
          <span class="font-normal text-muted-foreground">({{ conversations.length }})</span>
        </CardTitle>
        <Button v-if="projectId" variant="outline" size="sm" @click="viewAllConversations">
          View All Conversations
        </Button>
      </div>
    </CardHeader>
    <CardContent class="flex flex-col gap-3">
      <AppLoader v-if="isLoading" variant="inline" subject="conversations" />
      <AppError v-else-if="error" title="Failed to load conversations" :error="castError" variant="table" />
      <AppEmpty v-else-if="!conversations.length" subject="conversations" variant="table" />
      <template v-else>
        <ConversationsHourlyChart :conversations="conversations" :timezone="timezone" />
        <div class="flex flex-wrap gap-x-6 gap-y-1 text-sm">
          <span class="text-muted-foreground">
            Avg CQI: <span class="font-semibold text-foreground">{{ avgCqi ?? '—' }}</span>
          </span>
          <span class="text-muted-foreground">
            Compliant: <span class="font-semibold text-foreground">{{ compliantSummary }}</span>
          </span>
        </div>
      </template>
    </CardContent>
  </Card>
</template>

<script setup lang="ts">
import { MessageSquareIcon } from 'lucide-vue-next';
import type { FetchError } from 'ofetch';

import type { WorkShiftConversationItem } from '~/client';
import ConversationsHourlyChart from '~/components/workshift/review/ConversationsHourlyChart.vue';

interface Props {
  conversations: WorkShiftConversationItem[];
  projectId: string | null;
  canvasserId: string | null;
  isLoading: boolean;
  error: unknown;
  timezone: string;
}

const props = defineProps<Props>();

// AppError expects a typed FetchError; the query error surfaces here as
// `unknown` since the useQuery call lives in the page, not this component.
const castError = computed<FetchError<any> | null>(() => (props.error as FetchError<any> | null) ?? null);

const avgCqi = computed(() => {
  const scored = props.conversations.filter((c) => c.evaluation_cqi !== null);
  if (!scored.length) return null;
  return Math.round(scored.reduce((total, c) => total + (c.evaluation_cqi ?? 0), 0) / scored.length);
});

const compliantSummary = computed(() => {
  const judged = props.conversations.filter((c) => c.evaluation_compliant !== null);
  if (!judged.length) return '—';
  return `${judged.filter((c) => c.evaluation_compliant).length} of ${judged.length}`;
});

// The list page supports a `canvasser_ids` query filter — this navigates
// project-scoped, pre-filtered to this shift's canvasser.
function viewAllConversations() {
  if (!props.projectId) return;
  navigateTo({ path: `/projects/${props.projectId}/conversations`, query: { canvasser_ids: props.canvasserId } });
}
</script>
