<template>
  <Card class="border-2" data-testid="workshift-review-kpis">
    <CardContent class="grid grid-cols-2 gap-x-4 gap-y-5 py-5 sm:grid-cols-4">
      <div class="flex flex-col">
        <span class="text-sm text-muted-foreground">Doors Knocked</span>
        <span class="text-xl font-semibold">{{ kpis.doors ?? '—' }}</span>
      </div>
      <div class="flex flex-col">
        <span class="text-sm text-muted-foreground">Flagged Records</span>
        <span class="text-xl font-semibold" :class="flaggedRecordsRed ? 'text-red-700' : ''">
          {{ kpis.flagged_records ?? '—' }}
        </span>
      </div>
      <div class="flex flex-col">
        <span class="text-sm text-muted-foreground">DPH</span>
        <span class="text-xl font-semibold">{{ kpis.dph?.toFixed(1) ?? '—' }}</span>
      </div>
      <div class="flex flex-col">
        <span class="text-sm text-muted-foreground">Surveys ({{ Math.round((kpis.survey_rate ?? 0) * 100) }}%)</span>
        <span class="text-xl font-semibold">{{ kpis.surveys ?? '—' }}</span>
      </div>
      <div class="flex flex-col">
        <span class="text-sm text-muted-foreground">Wall Clock</span>
        <span class="text-xl font-semibold">{{ formatHoursHms(kpis.wall_clock_hours) }}</span>
      </div>
      <div class="flex flex-col">
        <span class="text-sm text-muted-foreground">Net Hours</span>
        <span class="text-xl font-semibold">{{ formatHoursHms(kpis.net_hours) }}</span>
      </div>
      <div class="flex flex-col">
        <span class="text-sm text-muted-foreground">Total Breaks</span>
        <span class="text-xl font-semibold" :class="totalBreaksRed ? 'text-red-700' : ''">
          {{ formatMinutesHms(kpis.total_break_min) }}
        </span>
      </div>
      <div class="flex flex-col">
        <span class="text-sm text-muted-foreground">Allowed Breaks</span>
        <span class="text-xl font-semibold">{{ formatMinutesHms(kpis.allowed_break_min) }}</span>
      </div>
    </CardContent>
  </Card>
</template>

<script setup lang="ts">
import type { ReviewKpis } from '~/client';

interface Props {
  kpis: ReviewKpis;
}

const props = defineProps<Props>();

const flaggedRecordsRed = computed(() => (props.kpis.flagged_records ?? 0) > 0);

const totalBreaksRed = computed(
  () =>
    props.kpis.total_break_min != null &&
    props.kpis.allowed_break_min != null &&
    props.kpis.total_break_min > props.kpis.allowed_break_min
);
</script>
