import { getWorkShiftConversations, type GetWorkShiftConversationsResponse } from '~/client';

export function useWorkShiftConversationsQuery(workShiftId: Ref<string | undefined>, enabled?: Ref<boolean>) {
  return useQuery({
    key: () => ['workshift-conversations', workShiftId.value ?? ''],
    query: (): Promise<GetWorkShiftConversationsResponse> =>
      getWorkShiftConversations({
        composable: '$fetch',
        path: { work_shift_id: workShiftId.value as string },
      }),
    enabled: () => Boolean(workShiftId.value) && (enabled ? enabled.value : true),
    staleTime: 60_000,
  });
}
