import {
  createWorkShiftDataExportJob,
  type CreateWorkShiftDataExportJobResponse,
  type WorkShiftInteractionExportKind,
} from '~/client';

interface ExportArgs {
  workShiftId: string;
  kind: WorkShiftInteractionExportKind;
}

export const useExportWorkShiftData = defineMutation(() => {
  const { mutateAsync, asyncStatus, data } = useMutation({
    mutation: ({ workShiftId, kind }: ExportArgs): Promise<CreateWorkShiftDataExportJobResponse> =>
      createWorkShiftDataExportJob({
        composable: '$fetch',
        path: { work_shift_id: workShiftId },
        body: ref({ kind }),
      }),
    onError: (error) => {
      showToastError(error);
    },
  });

  return {
    exportWorkShiftData: mutateAsync,
    isExportingWorkShiftData: computed(() => asyncStatus.value === 'loading'),
    data,
  };
});
