<template>
  <section class="flex flex-col gap-6">
    <WorkshiftReviewQueueBar
      v-if="queueData"
      :shifts="queueData.shifts"
      :current-shift-id="workShiftId ?? ''"
      :review-date="reviewDateQuery ?? ''"
      :sort-key="reviewSortQuery"
      :project-id="queueProjectId ?? ''"
      :can-review="canReviewShift"
      :is-reviewed="processedForAdminManager?.is_reviewed ?? false"
      :reviewed-details="reviewedDetails"
      :is-reviewing="isReviewingWorkShift"
      :timezone="timezone"
      @mark-reviewed="handleMarkReviewed"
      @clear-review="handleClearReview"
    />

    <div class="flex flex-wrap items-center justify-between gap-4">
      <PageTitle title="Work Shift Details" />
    </div>

    <div class="flex flex-wrap justify-between items-center gap-4">
      <GoBackButton
        v-if="workShift?.project_id"
        subject="work shifts"
        :fallback-to="{ name: 'projects-id-workshifts', params: { id: workShift.project_id } }"
      />
      <div class="flex items-center gap-3">
        <template v-if="showRecalculate">
          <Button
            :loading="isRequestingWorkshiftRecalculate || isLoading"
            :append-icon="isRequestingWorkshiftRecalculate || isLoading ? undefined : RefreshCwIcon"
            data-testid="workshift-details-recalculate"
            @click="requestWorkshiftRecalculate"
          >
            Recalculate
          </Button>
        </template>
        <DropdownMenu v-if="isAdminOrManager && workShift">
          <DropdownMenuTrigger as-child>
            <Button :loading="isExportingWorkShiftData" :prepend-icon="FileUpIcon" :append-icon="ChevronDownIcon">
              Export Data
            </Button>
          </DropdownMenuTrigger>
          <DropdownMenuContent align="end">
            <DropdownMenuItem @click="handleExport('interactions')">Canvassing app data</DropdownMenuItem>
            <DropdownMenuItem @click="handleExport('sensors')">Sensors data</DropdownMenuItem>
          </DropdownMenuContent>
        </DropdownMenu>
        <template v-if="processedForAdminManager && canReviewShift && !queueBarVisible">
          <Button
            v-if="!processedForAdminManager.is_reviewed"
            :loading="isReviewingWorkShift"
            :prepend-icon="CheckCircle2Icon"
            data-testid="workshift-details-mark-reviewed"
            @click="handleMarkReviewed"
          >
            Mark as Reviewed
          </Button>
          <!-- Attribution and Clear Review live in a tooltip on the badge so the
               reviewed state stays compact and the row doesn't jump. -->
          <Tooltip v-else>
            <TooltipTrigger as-child>
              <Badge variant="success" class="cursor-default" data-testid="workshift-details-reviewed-badge">
                Reviewed
              </Badge>
            </TooltipTrigger>
            <TooltipContent side="bottom" class="flex flex-col items-start gap-2">
              <span v-if="reviewedDetails">
                by <InlineEntityUser :user-id="reviewedDetails.user_id" /> on
                {{ formatDateBasedOnType(reviewedDetails.timestamp, timezone) }}
              </span>
              <Button
                variant="outline"
                size="sm"
                :loading="isReviewingWorkShift"
                data-testid="workshift-details-clear-review"
                @click="handleClearReview"
              >
                Clear Review
              </Button>
            </TooltipContent>
          </Tooltip>
        </template>
        <Badge v-if="workShift?.status" :variant="getWorkshiftStatusBadge(workShift.status).variant">
          {{ getWorkshiftStatusBadge(workShift.status).label }}
        </Badge>
      </div>
    </div>

    <Alert v-if="isRecalculating" variant="warning" data-testid="workshift-details-recalculate-alert">
      <HourglassIcon class="size-5" />
      <AlertTitle>Recalculation is in progress</AlertTitle>
      <AlertDescription> This work shift is being recalculated. It may take some time. </AlertDescription>
    </Alert>
    <Alert
      v-else-if="showAutoGeneratedRecalculateHint"
      variant="info"
      data-testid="workshift-details-recalculate-alert"
    >
      <InfoIcon class="size-5" />
      <AlertTitle>Recalculation needed</AlertTitle>
      <AlertDescription>
        This work shift was auto-generated and its net hours and earnings haven't been calculated yet. Click Recalculate
        to compute the hours and create the earning.
      </AlertDescription>
    </Alert>

    <AppLoader v-if="isLoading || isRecalculating" subject="work shift details" />
    <AppError v-else-if="error" :error="error" title="Failed to load work shift details" />
    <AppEmpty v-else-if="!workShift" subject="work shift details" />

    <template v-else>
      <WorkshiftCanvasserDetails
        v-if="processedForCanvasser"
        :data="processedForCanvasser"
        :earned-balance-message="earnedBalanceMessage"
      />
      <WorkshiftSubcontractorCanvasserDetails
        v-else-if="processedForSubcontractorCanvasser"
        :data="processedForSubcontractorCanvasser"
      />
      <template v-else-if="processedForAdminManager">
        <WorkshiftReviewSummary
          :risk-level="reviewData?.app_flags?.risk_level ?? null"
          :flag-keys="reviewData?.flag_sections?.map((section) => section.key) ?? []"
          :late-start="processedForAdminManager.late_start ?? false"
          :is-timeouted="processedForAdminManager.is_timeouted"
          :data-complete="processedForAdminManager.data_complete"
        />

        <WorkshiftAdminManagerDetails :data="processedForAdminManager" :earned-balance-message="earnedBalanceMessage" />

        <!-- The whole review section waits for review_data as one unit — cards
             appearing piecemeal (e.g. the conversations chart rendering first,
             then jumping down when the sections above pop in) reads as broken. -->
        <AppLoader v-if="isReviewLoading" subject="review data" />
        <AppError v-else-if="reviewError" :error="reviewError" title="Failed to load review data" />

        <template v-else-if="reviewData">
          <WorkshiftReviewKpiTiles :kpis="reviewData.kpis" />

          <Card v-if="reviewData.failure_reason === 'no_data'">
            <CardContent class="pt-6 text-sm text-muted-foreground">
              No location or interaction data was recorded for this work shift, so there was nothing to analyze for
              fraud.
            </CardContent>
          </Card>

          <WorkshiftReviewFlagSections
            :sections="reviewData.flag_sections ?? []"
            :app-flags="reviewData.app_flags ?? null"
            :kpis="reviewData.kpis"
            :timezone="displayTimezone"
            @highlight="onHighlight"
          />

          <!-- `isolate` caps the map/table-header z-indexes inside this card so
               they can't paint over the sticky queue bar above. -->
          <div ref="logCardRef" class="isolate">
            <WorkshiftReviewInteractionLog
              v-if="logCardInView"
              v-model:selected-row-id="selectedRowId"
              :log-rows="reviewData.log_rows ?? []"
              :map-bounds="reviewData.map_bounds ?? null"
              :highlighted-key="highlightedKey"
              :work-shift-id="workShiftId ?? ''"
              :stats-available="statsAvailable"
              :view-data-available="viewDataAvailable"
              :timezone="displayTimezone"
              @update:highlighted-key="highlightedKey = $event"
            />
            <Card v-else>
              <CardContent class="flex h-32 items-center justify-center text-sm text-muted-foreground">
                Scroll down to load the interaction log.
              </CardContent>
            </Card>
          </div>

          <div class="grid gap-6 lg:grid-cols-2">
            <WorkshiftReviewTimeline
              :timeline="reviewData.timeline ?? {}"
              :log-rows="reviewData.log_rows ?? []"
              :timezone="displayTimezone"
            />
            <WorkshiftReviewConversations
              :conversations="conversationsData?.items ?? []"
              :project-id="processedForAdminManager.project_id ?? null"
              :canvasser-id="processedForAdminManager.user_id ?? null"
              :is-loading="isConversationsLoading"
              :error="conversationsError"
              :timezone="displayTimezone"
            />
            <WorkshiftReviewCoaching
              v-if="coachingFeedbackId"
              :feedback="coachingFeedback ?? null"
              :is-loading="isCoachingFeedbackLoading"
            />
          </div>
        </template>
      </template>
    </template>
  </section>
</template>

<script setup lang="ts">
import { useIntersectionObserver } from '@vueuse/core';
import {
  getCoachingFeedbackDetails,
  getWorkShiftDetails,
  recalculateWorkShiftHoursAndEarnings,
  type ComApiModelWorkShiftDetailsWorkShiftDetailsForCanvasser,
  type ComApiModelWorkShiftDetailsWorkShiftDetailsForManager,
  type DailyReviewShift,
  type GetCoachingFeedbackDetailsResponse,
  type ReviewFlagKey,
  type WorkShiftDetailsForAdmin,
  type WorkShiftDetailsForSubcontractorCanvasser,
  type WorkShiftInteractionExportKind,
} from '~/client';
import type { EarnedBalanceMessage } from '~/types/workshifts/earnedBalance';
import { FileUpIcon, ChevronDownIcon, RefreshCwIcon, InfoIcon, HourglassIcon, CheckCircle2Icon } from 'lucide-vue-next';
import {
  isWorkShiftDetailsForCanvasser,
  isWorkShiftDetailsForSubcontractorCanvasser,
  isWorkShiftDetailsForAdminManager,
} from '~/utils/typeCheckers/workshifts';
import { getWorkshiftStatusBadge } from '~/constants/workshifts/workshiftStatuses';
import { useWorkShiftReviewDataQuery } from '~/queries/workshifts/reviewData';
import { useWorkShiftConversationsQuery } from '~/queries/workshifts/conversations';
import { useExportWorkShiftData } from '~/mutations/workshifts/exportWorkShiftData';
import { useReviewWorkShift } from '~/mutations/workshifts/reviewWorkShift';
import InlineEntityUser from '~/components/common/labeled-entity/InlineEntityUser.vue';
import { Tooltip, TooltipContent, TooltipTrigger } from '@/components/ui/tooltip';
import { formatDateBasedOnType } from '~/utils/formatDateToFormat';
import { sortDailyReviewShifts, type DailyReviewSortKey } from '~/utils/dailyReview';

definePageMeta({
  backLabel: 'work shift',
});

useHead({
  title: 'Work Shift Details',
});

const route = useRoute('workshifts-id');
const workShiftId = computed<string | undefined>(() => route.params.id?.toString());

const { isAdminOrManager, timezone } = useUserRole();

const {
  data: workShift,
  error,
  isLoading,
  refetch,
} = useQuery({
  key: () => ['workshift-details', workShiftId.value ?? ''],
  query: () => getWorkShiftDetails({ composable: '$fetch', path: { work_shift_id: workShiftId.value as string } }),
  staleTime: 0,
  enabled: computed(() => !!workShiftId.value && route.name === 'workshifts-id'),
});

const processedForCanvasser = computed((): ComApiModelWorkShiftDetailsWorkShiftDetailsForCanvasser | null => {
  return workShift.value && isWorkShiftDetailsForCanvasser(workShift.value) ? workShift.value : null;
});

const processedForSubcontractorCanvasser = computed((): WorkShiftDetailsForSubcontractorCanvasser | null => {
  return workShift.value && isWorkShiftDetailsForSubcontractorCanvasser(workShift.value) ? workShift.value : null;
});

const processedForAdminManager = computed(
  (): WorkShiftDetailsForAdmin | ComApiModelWorkShiftDetailsWorkShiftDetailsForManager | null => {
    return workShift.value && isWorkShiftDetailsForAdminManager(workShift.value) ? workShift.value : null;
  }
);

const { reviewWorkShiftMutation, isReviewingWorkShift } = useReviewWorkShift();

const reviewedDetails = computed(() => processedForAdminManager.value?.reviewed_details ?? null);

const canReviewShift = computed(
  () => isAdminOrManager.value && !!processedForAdminManager.value && processedForAdminManager.value.status !== 'ACTIVE'
);

// Day-queue navigation: when this work shift is opened from the Daily Review
// page (or via a queue prev/next), reviewDate/reviewSort are carried in the
// query string so the queue bar can render and Mark as Reviewed can advance.
const REVIEW_SORT_KEYS: DailyReviewSortKey[] = ['most-flags', 'lowest-survey', 'canvasser'];

const reviewDateQuery = computed<string | null>(() => {
  const raw = route.query.reviewDate;
  return typeof raw === 'string' && /^\d{4}-\d{2}-\d{2}$/.test(raw) ? raw : null;
});

const reviewSortQuery = computed<DailyReviewSortKey>(() => {
  const raw = route.query.reviewSort;
  return typeof raw === 'string' && (REVIEW_SORT_KEYS as string[]).includes(raw)
    ? (raw as DailyReviewSortKey)
    : 'most-flags';
});

const queueProjectId = computed<string | undefined>(() =>
  reviewDateQuery.value && isAdminOrManager.value ? workShift.value?.project_id : undefined
);
const queueDate = computed(() => reviewDateQuery.value ?? '');

// The query's own `enabled` gate already checks projectId + date truthiness,
// so this is a no-op fetch until both are present.
const { data: queueData } = useProjectDailyReviewQuery(queueProjectId, queueDate);

// Mirrors the bar's internal `currentIndex !== -1` render guard so the header
// review controls only step aside when the bar actually shows.
const queueBarVisible = computed(
  () => !!queueData.value && queueData.value.shifts.some((shift) => shift.id === workShiftId.value)
);

function handleClearReview() {
  const shiftId = processedForAdminManager.value?.id;
  if (!shiftId) return;
  reviewWorkShiftMutation({ workShiftId: shiftId, reviewed: false });
}

async function handleMarkReviewed() {
  const shiftId = processedForAdminManager.value?.id;
  if (!shiftId) return;

  // Snapshot the queue and pick the advance target BEFORE the mutation
  // resolves, since the mutation invalidates the daily-review query.
  let target: DailyReviewShift | null = null;
  if (queueData.value) {
    const queue = sortDailyReviewShifts(queueData.value.shifts, reviewSortQuery.value);
    const currentIndex = queue.findIndex((shift) => shift.id === shiftId);
    if (currentIndex !== -1) {
      target =
        queue.slice(currentIndex + 1).find((shift) => shift.is_reviewable && !shift.is_reviewed) ??
        queue[currentIndex + 1] ??
        null;
    }
  }

  await reviewWorkShiftMutation({ workShiftId: shiftId, reviewed: true });

  if (target && reviewDateQuery.value) {
    await navigateTo({
      name: 'workshifts-id',
      params: { id: target.id },
      query: { reviewDate: reviewDateQuery.value, reviewSort: reviewSortQuery.value },
    });
  }
}

const {
  data: reviewData,
  error: reviewError,
  isLoading: isReviewLoading,
} = useWorkShiftReviewDataQuery(
  workShiftId,
  computed(() => !!workShiftId.value && isAdminOrManager.value && route.name === 'workshifts-id')
);

const {
  data: conversationsData,
  isLoading: isConversationsLoading,
  error: conversationsError,
} = useWorkShiftConversationsQuery(
  workShiftId,
  computed(() => !!workShiftId.value && isAdminOrManager.value && route.name === 'workshifts-id')
);

// Coaching: page-owned query, enabled only when the details expose an id.
const coachingFeedbackId = computed(() => {
  const ws = processedForAdminManager.value;
  return ws && 'coaching_feedback_id' in ws ? (ws.coaching_feedback_id ?? null) : null;
});

const { data: coachingFeedback, isLoading: isCoachingFeedbackLoading } = useQuery({
  key: () => ['coaching-feedback-details', coachingFeedbackId.value ?? ''],
  query: (): Promise<GetCoachingFeedbackDetailsResponse> =>
    getCoachingFeedbackDetails({ composable: '$fetch', path: { feedback_id: coachingFeedbackId.value as string } }),
  enabled: computed(() => !!coachingFeedbackId.value),
});

const statsAvailable = computed(() =>
  (reviewData.value?.log_rows ?? []).some((row) => row.gap_min != null || row.dist_moved_ft != null)
);
const viewDataAvailable = computed(() => !!reviewData.value?.app_flags);

const selectedRowId = ref<number | null>(null);
const highlightedKey = ref<ReviewFlagKey | null>(null);
const logCardRef = useTemplateRef<HTMLElement>('logCardRef');
watch(workShiftId, () => {
  selectedRowId.value = null;
  highlightedKey.value = null;
});

// Lazy-mount the (heavy, map-carrying) interaction log card only once it
// scrolls into view, same pattern as the old interactions-map anchor.
const logCardInView = ref(false);
const OBSERVER_ROOT_MARGIN_PX = 200;

useIntersectionObserver(
  logCardRef,
  ([entry]) => {
    if (entry?.isIntersecting) logCardInView.value = true;
  },
  { rootMargin: `${OBSERVER_ROOT_MARGIN_PX}px` }
);

watch(workShiftId, async () => {
  logCardInView.value = false;
  await nextTick();
  const el = logCardRef.value;
  if (!el) return;
  const rect = el.getBoundingClientRect();
  const margin = OBSERVER_ROOT_MARGIN_PX;
  if (rect.top < window.innerHeight + margin && rect.bottom > -margin) {
    logCardInView.value = true;
  }
});

// Selecting a flag section force-mounts the lazy log card and scrolls it into
// view so the highlight is visible even when the card sits below the fold.
// Toggling off (null) just clears the selection without scrolling.
function onHighlight(key: ReviewFlagKey | null) {
  highlightedKey.value = highlightedKey.value === key ? null : key;
  if (highlightedKey.value) {
    logCardInView.value = true;
    logCardRef.value?.scrollIntoView({ behavior: 'smooth', block: 'start' });
  }
}

// Review times render in the VIEWER's timezone — one tz binding shared by the
// table, flag sections, timeline axis, and charts so they always agree. (The
// shift's own time_zone stays visible in the details card for reference.)
const displayTimezone = computed(() => timezone.value || 'UTC');

const earnedBalanceMessage = computed((): EarnedBalanceMessage | null => {
  const ws = workShift.value;
  // current_earned is computed server-side (applies the projected rate for ongoing shifts),
  // so it is populated for both ongoing and finished shifts. Absent on the subcontractor shape.
  if (!ws || !('current_earned' in ws) || ws.current_earned == null) return null;
  const amount = formatAmount(ws.current_earned);
  if (!ws.last_interaction_timestamp) return { amount, asOf: null };
  const asOf = formatDateTzToFormat(ws.last_interaction_timestamp, 'MM/dd/yyyy, hh:mm aaa', timezone.value);
  return { amount, asOf };
});

const { exportWorkShiftData, isExportingWorkShiftData, data: exportJob } = useExportWorkShiftData();

async function handleExport(kind: WorkShiftInteractionExportKind) {
  if (!workShiftId.value) return;
  await exportWorkShiftData({ workShiftId: workShiftId.value, kind });
  if (exportJob.value?.id) {
    await navigateTo({ name: 'exports-id', params: { id: exportJob.value.id } });
  }
}

const isRecalculating = computed(() => {
  const status = processedForAdminManager.value?.recalculation_status;
  return status === 'requested' || status === 'generating_report';
});

// Deliberately NOT !isRecalculating: 'generating_report' completion depends on a
// different worker process, so the button stays visible in that state as the
// manual recovery path if the completion flip never arrives (worker crash, lost
// Kafka message). Only 'requested' — where the recalc worker itself owns
// terminating the status — hides it.
const showRecalculate = computed(() => {
  const ws = processedForAdminManager.value;
  return !!ws && ws.recalculation_status !== 'requested';
});

const showAutoGeneratedRecalculateHint = computed(() => {
  const ws = processedForAdminManager.value;
  return !!ws?.is_auto_generated && ws.recalculation_status === null;
});

// When recalculation fully finishes (recalculation_status leaves the in-flight values
// 'requested' / 'generating_report'), the review card's data (log rows, KPIs, flags --
// all derived from view.json) is stale until this query refetches. The backend only
// flips to 'completed' after the regenerated view.json is persisted, so isRecalculating's
// falling edge is the signal: invalidate so the review card picks up the fresh view.json.
watch(isRecalculating, (recalculating, wasRecalculating) => {
  if (wasRecalculating && !recalculating) {
    const queryCache = useQueryCache();
    queryCache.invalidateQueries({ key: ['workshift-review-data', workShiftId.value ?? ''] });
  }
});

const { mutateAsync: requestWorkshiftRecalculate, isLoading: isRequestingWorkshiftRecalculate } = useMutation({
  mutation: () => recalculateWorkShiftHoursAndEarnings({ path: { work_shift_id: workShiftId.value ?? '' } }),
  key: () => ['workshift-recalculate', workShiftId.value ?? ''],
  onSuccess: async () => {
    const queryCache = useQueryCache();
    queryCache.invalidateQueries({ key: ['workshift-details', workShiftId.value ?? ''] });
    showToastSuccess('Recalculation requested');
  },
  onError(error) {
    showToastError(error);
  },
});

useTimeoutPoll(async () => {
  if (!isRecalculating.value) return;
  await refetch();
}, 15 * 1000); // 15 seconds
</script>
