import type { ReviewLogRow } from '~/client';

/**
 * Toggles a row's contact in a contact-id selection Set, returning a NEW Set
 * (never mutating `current`) so Vue's ref reactivity picks up the change.
 * No-ops (returns `current` unchanged) for rows with no interaction_id —
 * those can't be selected. Excluded rows ARE selectable: the selection bar
 * offers Restore for them.
 */
export function toggleContactSelection(current: Set<string>, row: Pick<ReviewLogRow, 'interaction_id'>): Set<string> {
  if (!row.interaction_id) return current;
  const next = new Set(current);
  if (next.has(row.interaction_id)) next.delete(row.interaction_id);
  else next.add(row.interaction_id);
  return next;
}

/**
 * Splits a contact-id selection into excludable (currently active) and
 * restorable (currently excluded) ids, based on the rows' exclusion state.
 * Rows sharing an interaction_id share exclusion state, so first-match wins.
 */
export function splitSelectionByExclusion(
  selected: Set<string>,
  rows: Array<Pick<ReviewLogRow, 'interaction_id' | 'is_excluded'>>
): { activeIds: string[]; excludedIds: string[] } {
  const excludedById = new Map<string, boolean>();
  for (const row of rows) {
    if (row.interaction_id && !excludedById.has(row.interaction_id)) {
      excludedById.set(row.interaction_id, Boolean(row.is_excluded));
    }
  }
  const activeIds: string[] = [];
  const excludedIds: string[] = [];
  for (const id of selected) {
    if (excludedById.get(id)) excludedIds.push(id);
    else activeIds.push(id);
  }
  return { activeIds, excludedIds };
}
