<template>
  <div class="flex flex-col gap-2">
    <!-- Legend (2 series → always present; labels carry identity, not color alone) -->
    <div class="flex flex-wrap items-center gap-x-4 gap-y-1 text-xs text-muted-foreground">
      <span class="inline-flex items-center gap-1.5">
        <span class="inline-block size-2.5 rounded-full" :style="{ backgroundColor: EVALUATED_HEX }" />
        Evaluated <span class="font-semibold tabular-nums text-foreground">{{ evaluatedTotal }}</span>
      </span>
      <span class="inline-flex items-center gap-1.5">
        <span class="inline-block size-2.5 rounded-full" :style="{ backgroundColor: TIMED_OUT_HEX }" />
        Timed out / discarded <span class="font-semibold tabular-nums text-foreground">{{ timedOutTotal }}</span>
      </span>
    </div>

    <div class="relative" @mouseleave="hovered = null">
      <svg :viewBox="`0 0 ${WIDTH} ${HEIGHT}`" class="w-full" role="img" aria-label="Conversations per hour">
        <!-- recessive gridline + y max label -->
        <line :x1="PAD_L" :y1="PLOT_TOP" :x2="WIDTH - PAD_R" :y2="PLOT_TOP" stroke="#e5e7eb" stroke-width="1" />
        <line
          :x1="PAD_L"
          :y1="PLOT_TOP + plotH / 2"
          :x2="WIDTH - PAD_R"
          :y2="PLOT_TOP + plotH / 2"
          stroke="#f1f5f9"
          stroke-width="1"
        />
        <text :x="PAD_L - 4" :y="PLOT_TOP + 4" text-anchor="end" class="fill-gray-400" font-size="9">
          {{ maxCount }}
        </text>

        <g v-for="bucket in buckets" :key="bucket.hour">
          <!-- hover hit target: full column -->
          <rect
            :x="bucket.x - barGap / 2"
            :y="PLOT_TOP"
            :width="barW + barGap"
            :height="plotH + 14"
            fill="transparent"
            @mouseenter="hovered = bucket"
          />
          <!-- timed-out segment (bottom, anchored to baseline, rounded data-end only when top) -->
          <rect
            v-if="bucket.timedOut"
            :x="bucket.x"
            :y="baseline - segH(bucket.timedOut)"
            :width="barW"
            :height="segH(bucket.timedOut)"
            :rx="bucket.evaluated ? 0 : 3"
            :fill="TIMED_OUT_HEX"
            :opacity="hovered && hovered.hour !== bucket.hour ? 0.35 : 1"
          />
          <!-- evaluated segment (top) with a 2px surface gap to the segment below -->
          <rect
            v-if="bucket.evaluated"
            :x="bucket.x"
            :y="baseline - segH(bucket.timedOut) - (bucket.timedOut ? 2 : 0) - segH(bucket.evaluated)"
            :width="barW"
            :height="segH(bucket.evaluated)"
            :rx="3"
            :fill="EVALUATED_HEX"
            :opacity="hovered && hovered.hour !== bucket.hour ? 0.35 : 1"
          />
          <!-- x label every other hour, muted ink -->
          <text
            v-if="bucket.hour % 2 === 0"
            :x="bucket.x + barW / 2"
            :y="baseline + 12"
            text-anchor="middle"
            class="fill-gray-400"
            font-size="9"
          >
            {{ formatHourLabel(bucket.hour) }}
          </text>
        </g>
      </svg>

      <!-- tooltip -->
      <div
        v-if="hovered"
        class="pointer-events-none absolute -top-1 rounded-md border bg-card px-2 py-1 text-xs shadow-md"
        :style="{ left: `${((hovered.x + barW / 2) / WIDTH) * 100}%`, transform: 'translateX(-50%)' }"
      >
        <span class="font-medium">{{ formatHourLabel(hovered.hour) }}</span>
        · {{ hovered.evaluated }} evaluated · {{ hovered.timedOut }} timed out / discarded
      </div>
    </div>
  </div>
</template>

<script setup lang="ts">
// Hourly conversation counts for one work shift — stacked bars (evaluated vs
// timed out). Palette validated with the dataviz six-checks (blue+amber,
// CVD ΔE 141.8); the amber contrast WARN is relieved by the labeled legend,
// text-ink counts, and the hover tooltip.
//
// Promoted from components/prototypes/daily-project-review/ConversationsHourlyChart.vue
// with a local minimal input type (no dependency on the prototype's fixture
// data) and real-data bucketing: hour is derived from the ISO `created_at`
// timestamp instead of a precomputed fixture field.
//
// Both series are defined positively, each keyed on the real ConversationStatus
// value (there is no literal 'timed_out' ConversationStatus):
//  - Evaluated  = status === 'completed'.
//  - Timed out / discarded = status === 'discarded'. This is the best available
//    proxy on WorkShiftConversationItem — it has no `canvassing_state` field to
//    read CanvassingState.TIMED_OUT from directly. CanvassingState.TIMED_OUT's
//    `.lifecycle` does map to ConversationStatus.DISCARDED (backend
//    modules/common/src/com/model/conversation_status.py), but DISCARDED is a
//    superset of timed-out: other paths also mark a conversation discarded,
//    e.g. audio-readiness failures via `bulk_mark_readiness_discarded`
//    (backend modules/common/src/com/sql/conversation.py). Hence the "/
//    discarded" in the label — this series is not a pure timeout count.
// `new`/`processing`/`failed` conversations belong to neither series (by
// design) and are excluded from both bucket counts and the totals below.
import { computed, ref } from 'vue';
import { formatDateTzToFormat } from '~/utils/formatDateToFormat';

export interface ChartConversation {
  created_at: string;
  status: string;
  evaluation_cqi: number | null;
}

const props = defineProps<{ conversations: ChartConversation[]; timezone: string }>();

const EVALUATED_STATUS = 'completed';
const TIMED_OUT_STATUS = 'discarded';

const EVALUATED_HEX = '#2563eb';
const TIMED_OUT_HEX = '#f59e0b';

const WIDTH = 560;
const HEIGHT = 132;
const PAD_L = 20;
const PAD_R = 4;
const PLOT_TOP = 6;
const baseline = HEIGHT - 18;
const plotH = baseline - PLOT_TOP;

interface Bucket {
  hour: number;
  evaluated: number;
  timedOut: number;
  x: number;
}

// Bucket in the shift's own timezone (useUserRole().timezone, threaded down
// from the page), not the viewing browser's local timezone — otherwise this
// chart's hour buckets disagree with every other timezone-aware card on the
// review page.
// 0-23 -> "12 AM" / "1 PM" — matches the AM/PM style used across the page.
function formatHourLabel(hour: number): string {
  const h12 = hour % 12 === 0 ? 12 : hour % 12;
  return `${h12} ${hour < 12 ? 'AM' : 'PM'}`;
}

function hourOf(createdAt: string): number {
  return parseInt(formatDateTzToFormat(createdAt, 'HH', props.timezone), 10);
}

const hourRange = computed(() => {
  const hours = props.conversations.map((c) => hourOf(c.created_at));
  if (!hours.length) return { min: 8, max: 20 };
  return { min: Math.min(...hours), max: Math.max(...hours) };
});

const barGap = 4;
const barW = computed(() => {
  const n = hourRange.value.max - hourRange.value.min + 1;
  return Math.max(6, (WIDTH - PAD_L - PAD_R) / n - barGap);
});

const buckets = computed<Bucket[]>(() => {
  const { min, max } = hourRange.value;
  const out: Bucket[] = [];
  for (let hour = min; hour <= max; hour += 1) {
    const inHour = props.conversations.filter((c) => hourOf(c.created_at) === hour);
    out.push({
      hour,
      evaluated: inHour.filter((c) => c.status === EVALUATED_STATUS).length,
      timedOut: inHour.filter((c) => c.status === TIMED_OUT_STATUS).length,
      x: PAD_L + (hour - min) * (barW.value + barGap) + barGap / 2,
    });
  }
  return out;
});

const maxCount = computed(() => Math.max(1, ...buckets.value.map((b) => b.evaluated + b.timedOut)));

function segH(count: number): number {
  return count === 0 ? 0 : Math.max(3, (count / maxCount.value) * (plotH - 8));
}

const evaluatedTotal = computed(() => props.conversations.filter((c) => c.status === EVALUATED_STATUS).length);
const timedOutTotal = computed(() => props.conversations.filter((c) => c.status === TIMED_OUT_STATUS).length);

const hovered = ref<Bucket | null>(null);
</script>
