import { formatHoursDuration } from '~/utils/formatHours';

// ---------------------------------------------------------------------------
// Unified duration display. Formatting delegates to the app's standard
// formatter (utils/formatHours.formatHoursDuration — adaptive "16m 50s" /
// "12h 54m"); these wrappers add the null/zero display and round sub-minute
// values to whole seconds ("24s") instead of the shared formatter's
// millisecond output ("24s 0ms"), which is noise at review granularity.
// ---------------------------------------------------------------------------
function format(hours: number): string {
  const totalSeconds = hours * 3600;
  if (totalSeconds < 60) {
    const rounded = Math.round(totalSeconds);
    // 59.6s rounds up to a whole minute — hand it to the shared formatter as
    // exactly 1 minute so it can't fall back into its millisecond branch.
    return rounded < 60 ? `${rounded}s` : formatHoursDuration(60 / 3600);
  }
  return formatHoursDuration(hours);
}

export function formatHoursHms(hours: number | null | undefined): string {
  if (hours === null || hours === undefined || !Number.isFinite(hours)) return '—';
  if (hours === 0) return '0h';
  return format(hours);
}

export function formatMinutesHms(minutes: number | null | undefined): string {
  if (minutes === null || minutes === undefined || !Number.isFinite(minutes)) return '—';
  if (minutes === 0) return '0m';
  return format(minutes / 60);
}

export function formatDurationHms(totalSec: number | null | undefined): string {
  if (totalSec === null || totalSec === undefined || !Number.isFinite(totalSec)) return '—';
  if (totalSec === 0) return '0s';
  return format(totalSec / 3600);
}
