<template>
  <Card data-testid="workshift-review-flag-sections">
    <CardHeader class="pb-2">
      <div class="flex flex-wrap items-center justify-between gap-2">
        <CardTitle class="flex items-center gap-2 text-sm">
          <ShieldAlertIcon class="size-4" /> Fraud Risk Assessment
        </CardTitle>
        <span :class="['rounded-full px-2.5 py-0.5 text-xs font-semibold uppercase', risk.badgeClass]">
          {{ risk.label }}
        </span>
      </div>
    </CardHeader>
    <CardContent class="flex flex-col gap-3">
      <p v-if="!hasContent" class="text-sm text-muted-foreground">No fraud flags raised for this shift.</p>

      <template v-else>
        <!-- Risk narrative — ported from the removed WorkshiftRiskNarrative component -->
        <div v-if="riskReasons.length" class="flex flex-col gap-2">
          <div
            v-if="appFlags?.device_did_not_move"
            data-testid="device-did-not-move-banner"
            class="rounded-md border border-red-400 bg-red-50 px-3 py-2 text-sm text-red-800 dark:bg-red-950/40 dark:text-red-200"
          >
            <span class="font-semibold">GPS Issue — Device Did Not Move.</span>
            Device GPS barely changed across the session while houses were spread out<span
              v-if="appFlags.median_device_distance_ft != null"
            >
              — median {{ Math.round(appFlags.median_device_distance_ft) }} ft from each house worked</span
            >.
          </div>
          <ul class="flex flex-col gap-1.5">
            <li v-for="(reason, i) in riskReasons" :key="i" class="flex items-start gap-2 text-sm">
              <span
                :class="[
                  'mt-0.5 shrink-0 rounded px-1.5 py-0.5 text-[10px] font-semibold uppercase',
                  getRiskLevel(reason.level).badgeClass,
                ]"
              >
                {{ getRiskLevel(reason.level).label }}
              </span>
              <span>
                {{ reason.text }}
                <span class="text-muted-foreground">· {{ getRiskConfidenceLabel(reason.confidence) }}</span>
              </span>
            </li>
          </ul>
        </div>

        <!-- One accordion per tripped flag category -->
        <div v-if="sections.length" class="overflow-hidden rounded-lg border">
          <div v-for="section in sections" :key="section.key" class="border-b last:border-b-0">
            <!-- Section header -->
            <button
              type="button"
              class="flex w-full items-center gap-3 px-3 py-2 text-left transition-colors hover:bg-muted/60"
              @click="toggleSection(section.key)"
            >
              <div
                class="flex size-7 shrink-0 items-center justify-center rounded-md"
                :class="REVIEW_FLAG_CONFIG[section.key].accentBg"
              >
                <component
                  :is="REVIEW_FLAG_CONFIG[section.key].icon"
                  class="size-4"
                  :class="REVIEW_FLAG_CONFIG[section.key].accentText"
                />
              </div>
              <span class="text-sm font-semibold">{{ REVIEW_FLAG_CONFIG[section.key].label }}</span>
              <Badge v-if="section.confidence" :variant="CONFIDENCE_CONFIG[section.confidence].variant" size="sm">
                {{ CONFIDENCE_CONFIG[section.confidence].label }}
              </Badge>
              <span class="ml-auto text-xs text-muted-foreground">
                <template v-if="section.flagged_sec_total">
                  {{ formatDurationHms(section.flagged_sec_total) }} flagged ·
                </template>
              </span>
              <span
                class="w-6 text-right text-base font-bold tabular-nums"
                :class="REVIEW_FLAG_CONFIG[section.key].accentText"
              >
                {{ section.count }}
              </span>
              <ChevronRightIcon
                class="size-4 shrink-0 text-muted-foreground transition-transform"
                :class="openSections.has(section.key) ? 'rotate-90' : ''"
              />
            </button>

            <!-- Section body -->
            <div v-if="openSections.has(section.key)" class="border-t bg-muted/30 px-3 py-3">
              <div class="mb-2 flex flex-wrap items-start justify-between gap-2">
                <p class="max-w-3xl text-xs leading-5 text-muted-foreground">
                  {{ REVIEW_FLAG_CONFIG[section.key].explainer }}
                </p>
                <Button
                  v-if="(section.records ?? []).length"
                  variant="outline"
                  size="sm"
                  :prepend-icon="MapPinIcon"
                  @click="emit('highlight', section.key)"
                >
                  Highlight in Log
                </Button>
              </div>

              <!-- DPH outlier — shift-level metric, no per-interaction records -->
              <p v-if="section.key === 'dph_outlier'" class="text-sm">
                {{ dphSummary }}
              </p>

              <!-- Record table -->
              <div v-else class="overflow-x-auto rounded border bg-card">
                <table class="w-full min-w-[700px] text-left text-xs">
                  <thead class="bg-muted text-muted-foreground">
                    <tr class="[&>th]:whitespace-nowrap [&>th]:px-2 [&>th]:py-1.5 [&>th]:font-medium">
                      <th class="w-8">#</th>
                      <th>From</th>
                      <th>To</th>
                      <th>Details</th>
                      <th />
                    </tr>
                  </thead>
                  <tbody>
                    <tr
                      v-for="(record, index) in section.records ?? []"
                      :key="record.key"
                      class="border-t [&>td]:px-2 [&>td]:py-1.5"
                    >
                      <td class="text-muted-foreground">{{ index + 1 }}</td>
                      <td>
                        <template v-if="record.from_row">
                          <div class="font-medium">{{ record.from_row.address ?? '—' }}</div>
                          <div class="flex items-center gap-1.5 text-muted-foreground">
                            <span class="font-mono">{{ formatTime(record.from_row.ts) }}</span>
                            <template v-if="unifiedResponseEntry(record.from_row)">
                              <span
                                class="inline-block size-2.5 rounded-full"
                                :style="{ backgroundColor: unifiedResponseEntry(record.from_row)!.hex }"
                              />
                              {{ unifiedResponseEntry(record.from_row)!.label }}
                            </template>
                            <span v-else-if="record.from_row.response">{{ record.from_row.response }}</span>
                          </div>
                        </template>
                        <span v-else class="text-muted-foreground">—</span>
                      </td>
                      <td>
                        <div class="font-medium">{{ record.to_row.address ?? '—' }}</div>
                        <div class="flex items-center gap-1.5 text-muted-foreground">
                          <span class="font-mono">{{ formatTime(record.to_row.ts) }}</span>
                          <template v-if="unifiedResponseEntry(record.to_row)">
                            <span
                              class="inline-block size-2.5 rounded-full"
                              :style="{ backgroundColor: unifiedResponseEntry(record.to_row)!.hex }"
                            />
                            {{ unifiedResponseEntry(record.to_row)!.label }}
                          </template>
                          <span v-else-if="record.to_row.response">{{ record.to_row.response }}</span>
                        </div>
                      </td>
                      <td class="whitespace-nowrap tabular-nums">{{ recordDetails(section.key, record) }}</td>
                      <td>
                        <Badge v-if="record.kind" :variant="recordBadgeVariant(record.kind)" size="sm">
                          {{ record.kind }}
                        </Badge>
                      </td>
                    </tr>
                  </tbody>
                </table>
              </div>
            </div>
          </div>
        </div>
      </template>
    </CardContent>
  </Card>
</template>

<script setup lang="ts">
import { ChevronRightIcon, MapPinIcon, ShieldAlertIcon } from 'lucide-vue-next';

import type { BadgeVariants } from '~/components/ui/badge';
import type {
  CanvassingAppFlags,
  ReviewFlagKey,
  ReviewFlagRecord,
  ReviewFlagRecordEnd,
  ReviewKpis,
  ReviewFlagSection,
} from '~/client';
import { getRiskConfidenceLabel, getRiskLevel } from '~/constants/workshifts/canvassingAppStatsConfig';
import {
  CONFIDENCE_CONFIG,
  REVIEW_FLAG_CONFIG,
  UNIFIED_RESPONSE_CONFIG,
  type UnifiedResponseEntry,
} from '~/constants/workshifts/reviewConfig';

interface Props {
  sections: ReviewFlagSection[];
  appFlags: CanvassingAppFlags | null;
  kpis: ReviewKpis;
  timezone: string;
}

const props = defineProps<Props>();

const emit = defineEmits<{ highlight: [key: ReviewFlagKey] }>();

const risk = computed(() => getRiskLevel(props.appFlags?.risk_level ?? 'none'));
const riskReasons = computed(() => props.appFlags?.risk_reasons ?? []);
const hasContent = computed(() => props.sections.length > 0 || riskReasons.value.length > 0);

// Accordion open/close state — local only, reset is not needed here since the
// component is re-mounted per work shift (keyed by the page's shift id).
const openSections = ref(new Set<ReviewFlagKey>());
function toggleSection(key: ReviewFlagKey): void {
  const next = new Set(openSections.value);
  if (next.has(key)) next.delete(key);
  else next.add(key);
  openSections.value = next;
}

function formatTime(ts: string | null | undefined): string {
  if (!ts) return '—';
  return formatDateTzToFormat(ts, 'hh:mm aaa', props.timezone);
}

// `unified_response` is already resolved to the shared enum by the backend, so
// this looks it up directly rather than re-deriving it from a raw app response
// (that's what `getUnifiedResponseConfig` is for — resolving a raw string).
function unifiedResponseEntry(row: ReviewFlagRecordEnd): UnifiedResponseEntry | null {
  return row.unified_response ? UNIFIED_RESPONSE_CONFIG[row.unified_response] : null;
}

function recordBadgeVariant(kind: string): BadgeVariants {
  return kind === 'HIGH' || kind === 'Off-site GPS' ? 'destructive' : 'warning';
}

// Type-specific details string for a record row, ported from the prototype's
// `recordDetails` (daily-project-review-workshift.vue:1083-1111), re-keyed to
// backend `ReviewFlagKey` values and the `ReviewFlagRecord` field shape.
function recordDetails(key: ReviewFlagKey, record: ReviewFlagRecord): string {
  switch (key) {
    case 'rapid_response':
      return `Gap ${formatMinutesHms(record.gap_min)}`;
    case 'impossible_speed': {
      const parts = [
        record.mph !== null && record.mph !== undefined ? `${record.mph.toFixed(1)} mph` : null,
        record.distance_ft !== null && record.distance_ft !== undefined ? `${Math.round(record.distance_ft)} ft` : null,
        `gap ${formatMinutesHms(record.gap_min)}`,
      ];
      return parts.filter(Boolean).join(' · ');
    }
    case 'off_site_gps':
      return record.distance_ft !== null && record.distance_ft !== undefined
        ? `${Math.round(record.distance_ft)} ft from house`
        : '—';
    case 'stationary_device':
      return record.distance_ft !== null && record.distance_ft !== undefined
        ? `${Math.round(record.distance_ft)} ft moved`
        : '—';
    case 'out_of_hours':
      return '—';
    case 'extra_breaks':
      return `Gap ${formatMinutesHms(record.gap_min)} · excess ${formatDurationHms(record.flagged_sec)}`;
    case 'no_answer_streak':
    case 'survey_streak':
      return `${record.run_length ?? '—'} doors in a row`;
    case 'dph_outlier':
      return '—';
  }
}

// DPH outlier summary line — shift-level metric, no per-interaction records.
// Ported from the prototype's `dphSummary` (daily-project-review-workshift.vue:1161-1166).
const dphSummary = computed(() => {
  const value = props.kpis.dph != null ? props.kpis.dph.toFixed(1) : '—';
  if (props.appFlags?.high_dph_outlier) {
    return `Shift DPH ${value} — above the high threshold (≥ 25 doors/hour).`;
  }
  if (props.appFlags?.low_dph_outlier) {
    return `Shift DPH ${value} — below the low threshold (< 15 doors/hour with 30+ doors).`;
  }
  return `Shift DPH ${value}.`;
});
</script>
