<template>
  <Card
    v-if="currentIndex !== -1"
    class="sticky top-0 z-20 border-2 bg-background/95 shadow-[0_6px_16px_rgba(0,0,0,0.06)] backdrop-blur"
    data-testid="workshift-queue-bar"
  >
    <CardContent class="flex flex-wrap items-center justify-between gap-4 py-3">
      <div class="flex items-center gap-2">
        <Button
          variant="outline"
          size="icon"
          aria-label="Previous shift"
          :disabled="!prevShift"
          data-testid="workshift-queue-prev"
          @click="goTo(prevShift)"
        >
          <ChevronLeftIcon class="size-4" />
        </Button>
        <div class="flex flex-col text-center">
          <span class="text-sm font-medium tabular-nums" data-testid="workshift-queue-position">
            Shift {{ currentIndex + 1 }} of {{ queue.length }}
          </span>
          <span
            v-if="formattedReviewDate"
            class="text-xs text-muted-foreground"
            data-testid="workshift-queue-review-date"
          >
            Reviewing {{ formattedReviewDate }}
          </span>
        </div>
        <Button
          variant="outline"
          size="icon"
          aria-label="Next shift"
          :disabled="!nextShift"
          data-testid="workshift-queue-next"
          @click="goTo(nextShift)"
        >
          <ChevronRightIcon class="size-4" />
        </Button>
      </div>

      <div class="flex min-w-48 flex-1 items-center gap-3">
        <span class="whitespace-nowrap text-sm text-muted-foreground">
          {{ progress.reviewed }} of {{ progress.reviewable }} reviewed
        </span>
        <Progress :model-value="progress.pct" class="h-2" data-testid="workshift-queue-progress" />
        <span
          v-if="allReviewed"
          class="inline-flex items-center gap-1 whitespace-nowrap text-sm font-medium text-green-700"
        >
          <CheckCircle2Icon class="size-4" />
          All shifts reviewed
        </span>
      </div>

      <div class="flex flex-wrap items-center gap-2">
        <template v-if="canReview">
          <Button
            v-if="!isReviewed"
            :loading="isReviewing"
            :prepend-icon="CheckCircle2Icon"
            data-testid="workshift-queue-mark-reviewed"
            @click="emit('mark-reviewed')"
          >
            Mark as Reviewed
          </Button>
          <!-- Attribution and Clear Review live in a tooltip on the badge so the
               reviewed state stays compact and the row doesn't jump. -->
          <Tooltip v-else>
            <TooltipTrigger as-child>
              <Badge variant="success" class="cursor-default" data-testid="workshift-queue-reviewed-badge">
                Reviewed
              </Badge>
            </TooltipTrigger>
            <TooltipContent side="bottom" class="flex flex-col items-start gap-2">
              <span v-if="reviewedDetails">
                by <InlineEntityUser :user-id="reviewedDetails.user_id" /> on
                {{ formatDateBasedOnType(reviewedDetails.timestamp, timezone) }}
              </span>
              <Button
                variant="outline"
                size="sm"
                :loading="isReviewing"
                data-testid="workshift-queue-clear-review"
                @click="emit('clear-review')"
              >
                Clear Review
              </Button>
            </TooltipContent>
          </Tooltip>
        </template>
        <Button variant="outline" as-child>
          <NuxtLink :to="{ name: 'projects-id-daily-review', params: { id: projectId }, query: { date: reviewDate } }">
            Day View
          </NuxtLink>
        </Button>
      </div>
    </CardContent>
  </Card>
</template>

<script setup lang="ts">
import { format, parseISO } from 'date-fns';
import { ChevronLeftIcon, ChevronRightIcon, CheckCircle2Icon } from 'lucide-vue-next';
import { Tooltip, TooltipContent, TooltipTrigger } from '@/components/ui/tooltip';
import type { DailyReviewShift, TimestampedActionWithComment } from '~/client';
import InlineEntityUser from '~/components/common/labeled-entity/InlineEntityUser.vue';
import { formatDateBasedOnType } from '~/utils/formatDateToFormat';
import { computeReviewProgress, sortDailyReviewShifts, type DailyReviewSortKey } from '~/utils/dailyReview';

const props = defineProps<{
  shifts: DailyReviewShift[];
  currentShiftId: string;
  reviewDate: string;
  sortKey: DailyReviewSortKey;
  projectId: string;
  canReview: boolean;
  isReviewed: boolean;
  reviewedDetails: TimestampedActionWithComment | null;
  isReviewing: boolean;
  timezone: string | undefined;
}>();

const emit = defineEmits<{
  'mark-reviewed': [];
  'clear-review': [];
}>();

const queue = computed(() => sortDailyReviewShifts(props.shifts, props.sortKey));
// reviewDate is a plain YYYY-MM-DD (already in the shift-local day), so parseISO
// keeps it calendar-accurate without any timezone shifting.
const formattedReviewDate = computed(() =>
  props.reviewDate ? format(parseISO(props.reviewDate), 'EEE, MMM d, yyyy') : ''
);
const currentIndex = computed(() => queue.value.findIndex((shift) => shift.id === props.currentShiftId));
const progress = computed(() => computeReviewProgress(props.shifts));
const allReviewed = computed(
  () => progress.value.reviewable > 0 && progress.value.reviewed === progress.value.reviewable
);

const prevShift = computed(() => (currentIndex.value > 0 ? queue.value[currentIndex.value - 1] : null));
const nextShift = computed(() =>
  currentIndex.value !== -1 && currentIndex.value < queue.value.length - 1 ? queue.value[currentIndex.value + 1] : null
);

function goTo(shift: DailyReviewShift | null | undefined) {
  if (!shift) return;
  navigateTo({
    name: 'workshifts-id',
    params: { id: shift.id },
    query: { reviewDate: props.reviewDate, reviewSort: props.sortKey },
  });
}
</script>
