import { excludeOrRestoreWorkShiftInteractions } from '~/client';

export const useExcludeInteractions = defineMutation(() => {
  const { mutateAsync: excludeInteractionsMutation, asyncStatus } = useMutation({
    mutation: (params: { workShiftId: string; interactionIds: string[]; excluded: boolean }) =>
      excludeOrRestoreWorkShiftInteractions({
        composable: '$fetch',
        path: { work_shift_id: params.workShiftId },
        body: ref({ interaction_ids: params.interactionIds, excluded: params.excluded }),
      }),
    onSuccess: async (_, params) => {
      showToastSuccess(params.excluded ? 'Interactions excluded successfully.' : 'Interactions restored successfully.');
      const queryCache = useQueryCache();
      await Promise.all([
        queryCache.invalidateQueries({ key: ['workshift-details', params.workShiftId] }),
        queryCache.invalidateQueries({ key: ['workshift-review-data', params.workShiftId] }),
        queryCache.invalidateQueries({ key: ['project-daily-review'] }),
      ]);
    },
    onError(error) {
      showToastError(error);
    },
  });

  return {
    excludeInteractionsMutation,
    isExcludingInteractions: computed(() => asyncStatus.value === 'loading'),
  };
});
