<template>
  <!-- Full-viewport review surface: the card spans the screen height and the
       map keeps at least half of it (basis-1/2 + shrink-0); the table scrolls
       inside the remainder. Falls back to natural height when there are no
       rows so the empty state isn't a screen-tall blank card. -->
  <Card data-testid="workshift-review-interaction-log" :class="logRows.length ? 'flex h-screen flex-col' : undefined">
    <CardHeader class="pb-2">
      <div class="flex flex-wrap items-center justify-between gap-2">
        <CardTitle class="flex items-center gap-2 text-sm">
          <MapPinIcon class="size-4" /> Interaction Log
          <span class="font-normal text-muted-foreground">({{ logRows.length }})</span>
        </CardTitle>
        <div class="flex flex-wrap items-center gap-2">
          <label class="flex cursor-pointer items-center gap-1.5 text-xs text-muted-foreground">
            <input
              v-model="detailedRoute"
              type="checkbox"
              class="size-3.5 cursor-pointer"
              :disabled="isRouteFetching"
            />
            Detailed Route
          </label>
          <button
            v-if="highlightedKey"
            type="button"
            class="inline-flex items-center gap-1 rounded-md px-2 py-1 text-xs font-medium"
            :class="[REVIEW_FLAG_CONFIG[highlightedKey].accentBg, REVIEW_FLAG_CONFIG[highlightedKey].accentText]"
            @click="clearHighlight"
          >
            Showing: {{ REVIEW_FLAG_CONFIG[highlightedKey].label }} ✕
          </button>
          <button
            v-if="flaggedCount"
            type="button"
            class="rounded border px-2 py-1 text-xs"
            :class="showFlaggedOnly ? 'border-red-300 bg-red-50 text-red-700' : 'text-muted-foreground'"
            @click="showFlaggedOnly = !showFlaggedOnly"
          >
            <FlagIcon class="mr-1 inline size-3" />{{ showFlaggedOnly ? 'Showing' : 'Show' }} flagged only ({{
              flaggedCount
            }})
          </button>
        </div>
      </div>
    </CardHeader>
    <CardContent class="flex min-h-0 flex-1 flex-col gap-3">
      <p v-if="routeError" class="text-xs text-destructive">Failed to load route data.</p>

      <CanvassingMap
        v-if="logRows.length"
        v-model:selected-interaction-id="mapSelectedInteractionId"
        :interactions="mapInteractions"
        :route-segments="routeData?.route_segments ?? []"
        :pause-intervals="routeData?.pause_intervals ?? []"
        :map-bounds="mapBounds"
        :show-fraud="false"
        :show-legend="false"
        :timezone="timezone"
        show-app-flags
        class="w-full min-h-0 shrink-0 grow basis-1/2"
        height-class="min-h-0 flex-1"
      />

      <p v-if="!logRows.length" class="py-2 text-sm text-muted-foreground">
        No interactions to display for this work shift.
      </p>

      <template v-else>
        <!-- Response summary — click to filter the log (and the map selection follows) -->
        <div class="flex flex-wrap items-center gap-1.5">
          <span class="mr-1 text-xs font-medium text-muted-foreground">Responses (click to filter)</span>
          <button
            v-for="entry in dispositionSummary"
            :key="entry.key"
            type="button"
            class="inline-flex items-center gap-1.5 rounded-md border px-2 py-1 text-xs transition-colors hover:bg-muted/60"
            :class="[
              dispositionFilter.has(entry.key) ? 'bg-muted ring-1 ring-foreground/20' : '',
              dispositionFilter.size && !dispositionFilter.has(entry.key) ? 'opacity-40' : '',
            ]"
            @click="toggleDispositionFilter(entry.key)"
          >
            <span class="inline-block size-2.5 rounded-full" :style="{ backgroundColor: entry.hex }" />
            {{ entry.label }}
            <span class="font-semibold tabular-nums">{{ entry.count }}</span>
          </button>
        </div>

        <!-- Selection bar — appears next to the table where the checkboxes live,
             not in the card header (which sits a full map above the rows). -->
        <div
          v-if="selectedContactIds.size > 0"
          class="flex items-center justify-between rounded border border-destructive/30 bg-destructive/5 px-2 py-1.5"
        >
          <span class="text-xs text-muted-foreground">
            {{ selectedContactIds.size }} {{ selectedContactIds.size === 1 ? 'interaction' : 'interactions' }} selected
          </span>
          <div class="flex items-center gap-2">
            <button
              type="button"
              class="text-xs text-muted-foreground underline-offset-2 hover:underline"
              @click="selectedContactIds = new Set()"
            >
              Clear
            </button>
            <Button
              v-if="selectionSplit.excludedIds.length > 0"
              type="button"
              variant="outline"
              size="sm"
              data-testid="workshift-review-restore-selected"
              :disabled="isExcludingInteractions"
              @click="restoreSelected"
            >
              Restore ({{ selectionSplit.excludedIds.length }})
            </Button>
            <Button
              v-if="selectionSplit.activeIds.length > 0"
              type="button"
              variant="destructive"
              size="sm"
              data-testid="workshift-review-exclude-selected"
              :disabled="isExcludingInteractions"
              @click="confirmOpen = true"
            >
              Exclude Selected ({{ selectionSplit.activeIds.length }})
            </Button>
          </div>
        </div>

        <div class="min-h-0 flex-1 overflow-auto rounded border">
          <table class="w-full min-w-[1000px] text-left text-xs">
            <thead class="sticky top-0 z-10 bg-muted text-muted-foreground">
              <tr class="[&>th]:whitespace-nowrap [&>th]:px-2 [&>th]:py-1.5 [&>th]:font-medium">
                <th class="w-8" />
                <th class="w-8">#</th>
                <th>Time</th>
                <th>Address</th>
                <th>Response</th>
                <th class="text-right">Gap</th>
                <th class="text-right">Min. walk</th>
                <th class="text-right">Over by</th>
                <th class="text-right">Canvasser moved</th>
                <th class="text-right">Dist. to house</th>
                <th class="text-right">Walking speed</th>
                <th>Flags</th>
              </tr>
            </thead>
            <tbody>
              <tr
                v-for="row in filteredRows"
                :key="row.id"
                class="cursor-pointer border-t [&>td]:whitespace-nowrap [&>td]:px-2 [&>td]:py-1.5"
                :class="[
                  (row.flags ?? []).length ? 'bg-red-50/60' : '',
                  selectedRowId === row.id ? 'bg-sky-100' : '',
                  row.is_excluded ? 'line-through opacity-50' : '',
                ]"
                @click="selectRow(row.id)"
              >
                <td @click.stop>
                  <input
                    v-if="row.interaction_id"
                    type="checkbox"
                    class="size-3.5 cursor-pointer"
                    data-testid="workshift-review-exclude-checkbox"
                    :checked="selectedContactIds.has(row.interaction_id)"
                    @click.stop
                    @change="toggleContact(row)"
                  />
                </td>
                <td class="text-muted-foreground">{{ row.id }}</td>
                <td class="font-mono text-muted-foreground">
                  {{ formatDateTzToFormat(row.ts, 'hh:mm:ss aaa', timezone) }}
                </td>
                <td class="max-w-[140px] truncate" :title="row.address ?? undefined">{{ row.address ?? '—' }}</td>
                <td>
                  <span v-if="row.unified_response" class="inline-flex items-center gap-1.5">
                    <span
                      class="inline-block size-2.5 rounded-full"
                      :style="{ backgroundColor: UNIFIED_RESPONSE_CONFIG[row.unified_response].hex }"
                    />
                    {{ UNIFIED_RESPONSE_CONFIG[row.unified_response].label }}
                  </span>
                  <span v-else-if="row.response">{{ row.response }}</span>
                  <span v-else class="text-muted-foreground">—</span>
                </td>
                <td class="text-right tabular-nums">
                  <span v-if="row.id === logRows[0]?.id" class="font-medium text-green-700">▶ Start</span>
                  <span v-else>{{ formatMinutesHms(row.gap_min) }}</span>
                </td>
                <td class="text-right tabular-nums text-green-700">
                  {{ row.allowance_sec != null ? formatDurationHms(row.allowance_sec) : '—' }}
                </td>
                <td class="text-right tabular-nums">
                  <div
                    v-if="row.extra_breaks_min != null && row.extra_breaks_min > 0"
                    class="flex items-center justify-end gap-1.5 whitespace-nowrap"
                  >
                    <Badge variant="warning" size="sm">BREAK {{ formatMinutesHms(row.extra_breaks_min) }}</Badge>
                    <span class="font-medium text-orange-600">+{{ formatMinutesHms(row.extra_breaks_min) }}</span>
                  </div>
                  <span v-else>—</span>
                </td>
                <td class="text-right tabular-nums">{{ formatStatsRowFeet(row.dist_moved_ft) }}</td>
                <td class="text-right tabular-nums">{{ formatStatsRowFeet(row.dist_from_ft) }}</td>
                <td class="text-right tabular-nums">{{ formatStatsRowSpeed(row.walking_speed_fps) }}</td>
                <td>
                  <div class="flex flex-wrap items-center gap-1.5">
                    <component
                      :is="REVIEW_FLAG_CONFIG[key].icon"
                      v-for="key in row.flags ?? []"
                      :key="key"
                      class="size-4"
                      :class="REVIEW_FLAG_CONFIG[key].accentText"
                      :title="REVIEW_FLAG_CONFIG[key].label"
                    />
                  </div>
                </td>
              </tr>
            </tbody>
          </table>
        </div>
      </template>

      <p v-if="!statsAvailable && viewDataAvailable" class="text-xs text-muted-foreground">
        This project's canvassing app didn't record per-interaction metrics for this shift, so the metric columns are
        unavailable.
      </p>
    </CardContent>
  </Card>

  <Dialog v-model:open="confirmOpen">
    <DialogContent class="max-w-md">
      <DialogHeader class="gap-y-2 text-left">
        <DialogTitle class="text-xl">Exclude {{ selectionSplit.activeIds.length }} interaction(s)?</DialogTitle>
        <DialogDescription class="text-base font-normal text-accent-foreground">
          The interactions stay visible struck-through, but hours, stats, the fraud report, and dashboards recalculate
          as if they never happened. Pay changes only while the earning is still pending or under review.
        </DialogDescription>
      </DialogHeader>
      <DialogFooter>
        <div class="flex flex-wrap justify-end gap-2">
          <DialogClose as-child>
            <Button variant="outline" class="h-10 px-4">Cancel</Button>
          </DialogClose>
          <Button
            variant="destructive"
            class="h-10 px-4"
            :loading="isExcludingInteractions"
            :disabled="isExcludingInteractions"
            @click="excludeSelected"
          >
            Exclude
          </Button>
        </div>
      </DialogFooter>
    </DialogContent>
  </Dialog>
</template>

<script setup lang="ts">
import { FlagIcon, MapPinIcon } from 'lucide-vue-next';

import type { InteractionPointView, MapBounds, ReviewFlagKey, ReviewLogRow, UnifiedResponseTypeEnum } from '~/client';
import {
  RESPONSE_TYPE_COLOR,
  formatStatsRowFeet,
  formatStatsRowSpeed,
} from '~/constants/workshifts/canvassingAppStatsConfig';
import { REVIEW_FLAG_CONFIG, UNIFIED_RESPONSE_CONFIG } from '~/constants/workshifts/reviewConfig';
import { useSimplifiedRoute } from '~/composables/useSimplifiedRoute';
import { useWorkShiftRouteWithInteractionsQuery } from '~/queries/workshifts/routeWithInteractions';
import { useExcludeInteractions } from '~/mutations/workshifts/excludeInteractions';

interface Props {
  logRows: ReviewLogRow[];
  mapBounds: MapBounds | null;
  highlightedKey: ReviewFlagKey | null;
  workShiftId: string;
  statsAvailable: boolean;
  viewDataAvailable: boolean;
  timezone: string;
}

const props = defineProps<Props>();

const emit = defineEmits<{ 'update:highlightedKey': [key: null] }>();

const selectedRowId = defineModel<number | null>('selectedRowId', { default: null });

function clearHighlight() {
  emit('update:highlightedKey', null);
}

function selectRow(id: number) {
  selectedRowId.value = selectedRowId.value === id ? null : id;
}

// ---------------------------------------------------------------------------
// Exclusion — contact-keyed selection (rows sharing an interaction_id are one
// voter contact and select together, since checkbox state derives from this
// Set). Both active and excluded rows are selectable; the selection bar
// splits the selection into an "Exclude selected" action (confirmation
// dialog) for active contacts and a direct "Restore" action for excluded
// ones. Selection is cleared whenever the shift changes.
// ---------------------------------------------------------------------------
const selectedContactIds = ref<Set<string>>(new Set());
const { excludeInteractionsMutation, isExcludingInteractions } = useExcludeInteractions();
const confirmOpen = ref(false);

const selectionSplit = computed(() => splitSelectionByExclusion(selectedContactIds.value, props.logRows));

function toggleContact(row: ReviewLogRow) {
  selectedContactIds.value = toggleContactSelection(selectedContactIds.value, row);
}

async function excludeSelected() {
  await excludeInteractionsMutation({
    workShiftId: props.workShiftId,
    interactionIds: selectionSplit.value.activeIds,
    excluded: true,
  });
  selectedContactIds.value = new Set();
  confirmOpen.value = false;
}

async function restoreSelected() {
  await excludeInteractionsMutation({
    workShiftId: props.workShiftId,
    interactionIds: selectionSplit.value.excludedIds,
    excluded: false,
  });
  selectedContactIds.value = new Set();
}

watch(
  () => props.workShiftId,
  () => {
    selectedContactIds.value = new Set();
  }
);

// Bridge between this table's 1-based selectedRowId and CanvassingMap's
// 0-based selected-interaction-id (see the mapInteractions id offset comment
// below) — get subtracts 1, set adds 1 back, both null-safe. Keeps the
// table's own selection logic (selectRow, row highlighting) in 1-based ids
// while CanvassingMap's clicks/selection stay in its native 0-based space.
const mapSelectedInteractionId = computed<number | null>({
  get: () => (selectedRowId.value == null ? null : selectedRowId.value - 1),
  set: (value) => {
    selectedRowId.value = value == null ? null : value + 1;
  },
});

// ---------------------------------------------------------------------------
// Map adapter — CanvassingMap consumes InteractionPointView[]. Every log row
// maps to an entry, even when it has no house location (location: null,
// InteractionPointView's location is nullable): CanvassingMap's stale-selection
// watch (components/canvassing/CanvassingMap.vue:799-802) clears
// selectedInteractionId whenever the selected id is absent from
// props.interactions entirely, so a row with missing coordinates must still be
// present in this list (just unrenderable as a pin) or clicking it would
// select-then-immediately-clear. `fraud` is intentionally null:
// ReviewLogRow.fraud (ReviewFraudInfo) has a different shape than the map's
// popup expects (InteractionFraudInfo, plain string reasons); app-flag rings
// (show-app-flags) carry the same signal instead.
// `response_color` is looked up directly from RESPONSE_TYPE_COLOR keyed by the
// already-unified `unified_response` — NOT via getResponseColor(raw, app),
// which expects a raw per-app response string plus the originating app to
// resolve it; ReviewLogRow carries neither, and feeding an already-unified
// value through that raw-response mapping would misresolve it.
// ---------------------------------------------------------------------------
// CanvassingMap labels pins as `id + 1` (its interaction ids are 0-based
// view_data ids), while this log's rows are 1-based (merge_log_rows assigns
// ids 1..N over the merged, time-sorted list). Convert at this boundary —
// id: row.id - 1 here, and the mapSelectedInteractionId bridge below — so
// table row #1 shows as map pin "1", not "2". CanvassingMap itself is left
// untouched since it's shared with the fraud report page.
// The map mirrors the table's filters (response chips, flagged-only,
// highlight) — it renders `filteredRows`, not all rows, so one filter bar
// drives both views. The map's own legend is hidden via :show-legend="false".
const mapInteractions = computed<InteractionPointView[]>(() =>
  filteredRows.value.map((row) => ({
    id: row.id - 1,
    ts: row.ts,
    location:
      row.house_lat != null && row.house_lon != null ? { latitude: row.house_lat, longitude: row.house_lon } : null,
    response: row.unified_response ?? 'other',
    response_color: RESPONSE_TYPE_COLOR[row.unified_response ?? 'none'],
    fraud: null,
    app_flag_reasons: (row.flags ?? []).map((key) => REVIEW_FLAG_CONFIG[key].label),
    counts_as_suspect: false,
    canvasser_location:
      row.user_lat != null && row.user_lon != null ? { latitude: row.user_lat, longitude: row.user_lon } : null,
    canvasser_distance_m: null,
  }))
);

// ---------------------------------------------------------------------------
// Route overlay — replaces the old Route & Interactions tab. Always on: the
// query lives in this card (sanctioned exception to the queries-in-page
// convention) and fires when the lazily-mounted card appears; the simplified
// route loads by default with a "Detailed Route" checkbox for the full track.
// ---------------------------------------------------------------------------
const workShiftIdRef = computed(() => props.workShiftId);
const { simplified: mapSimplified, isDetailed: isMapDetailed, toggle: toggleMapDetailed } = useSimplifiedRoute();

const {
  data: routeData,
  error: routeError,
  asyncStatus: routeAsyncStatus,
} = useWorkShiftRouteWithInteractionsQuery(
  workShiftIdRef,
  computed(() => Boolean(props.workShiftId)),
  mapSimplified
);

const isRouteFetching = computed(() => routeAsyncStatus.value === 'loading');

// Checkbox model over the simplified/detailed pair.
const detailedRoute = computed({
  get: () => isMapDetailed.value,
  set: () => toggleMapDetailed(),
});

// ---------------------------------------------------------------------------
// Filters — response summary chips (multi-select), flagged-only, and the
// highlighted-flag chip driven by the parent's fraud-flag sections. Composed
// as highlight ∧ dispositions ∧ flagged-only (all active filters must match).
// ---------------------------------------------------------------------------
const UNKNOWN_RESPONSE_KEY = 'unknown' as const;
type ResponseFilterKey = UnifiedResponseTypeEnum | typeof UNKNOWN_RESPONSE_KEY;

const showFlaggedOnly = ref(false);
const dispositionFilter = ref(new Set<ResponseFilterKey>());

function toggleDispositionFilter(key: ResponseFilterKey) {
  const next = new Set(dispositionFilter.value);
  if (next.has(key)) next.delete(key);
  else next.add(key);
  dispositionFilter.value = next;
}

const dispositionSummary = computed(() => {
  const counts = new Map<ResponseFilterKey, number>();
  for (const row of props.logRows) {
    const key: ResponseFilterKey = row.unified_response ?? UNKNOWN_RESPONSE_KEY;
    counts.set(key, (counts.get(key) ?? 0) + 1);
  }
  return [...counts.entries()]
    .sort((a, b) => b[1] - a[1])
    .map(([key, count]) => ({
      key,
      count,
      label: key === UNKNOWN_RESPONSE_KEY ? 'Unknown' : UNIFIED_RESPONSE_CONFIG[key].label,
      hex: key === UNKNOWN_RESPONSE_KEY ? RESPONSE_TYPE_COLOR.none : UNIFIED_RESPONSE_CONFIG[key].hex,
    }));
});

const flaggedCount = computed(() => props.logRows.filter((row) => (row.flags ?? []).length > 0).length);

const filteredRows = computed(() =>
  props.logRows.filter((row) => {
    if (props.highlightedKey && !(row.flags ?? []).includes(props.highlightedKey)) return false;
    const responseKey: ResponseFilterKey = row.unified_response ?? UNKNOWN_RESPONSE_KEY;
    if (dispositionFilter.value.size && !dispositionFilter.value.has(responseKey)) return false;
    if (showFlaggedOnly.value && (row.flags ?? []).length === 0) return false;
    return true;
  })
);
</script>
