import { reviewWorkShift } from '~/client';

export const useReviewWorkShift = defineMutation(() => {
  const { mutateAsync: reviewWorkShiftMutation, asyncStatus } = useMutation({
    mutation: (params: { workShiftId: string; reviewed: boolean; comment?: string | null }) =>
      reviewWorkShift({
        composable: '$fetch',
        path: { work_shift_id: params.workShiftId },
        body: ref({ reviewed: params.reviewed, comment: params.comment ?? null }),
      }),
    onSuccess: async (_, params) => {
      showToastSuccess(
        params.reviewed ? 'Work shift marked as reviewed successfully.' : 'Work shift review cleared successfully.'
      );
      const queryCache = useQueryCache();
      await Promise.all([
        queryCache.invalidateQueries({ key: ['project-daily-review'] }),
        queryCache.invalidateQueries({ key: ['project-daily-review-pending-dates'] }),
        queryCache.invalidateQueries({ key: ['workshift-details', params.workShiftId] }),
      ]);
    },
    onError(error) {
      showToastError(error);
    },
  });

  return {
    reviewWorkShiftMutation,
    isReviewingWorkShift: computed(() => asyncStatus.value === 'loading'),
  };
});
