<template>
  <Card data-testid="workshift-review-timeline">
    <CardHeader class="pb-2">
      <CardTitle class="flex items-center gap-2 text-sm">
        <ClockIcon class="size-4" /> Work &amp; Break Timeline
      </CardTitle>
    </CardHeader>
    <CardContent class="flex flex-col gap-2">
      <div v-for="row in rows" :key="row.key" class="flex flex-col gap-1">
        <div class="flex flex-wrap items-center gap-3 text-sm">
          <Badge :variant="row.kind === 'break' ? 'warning' : 'success'" size="sm">
            {{ row.kind === 'break' ? 'Break' : 'Work' }}
          </Badge>
          <span :class="row.kind === 'break' ? 'text-muted-foreground' : ''">
            from <span class="font-mono">{{ row.from }}</span> to <span class="font-mono">{{ row.to }}</span>
          </span>
          <span class="ml-auto text-muted-foreground">
            <template v-if="row.durationMin !== null">{{ formatMinutesHms(row.durationMin) }}</template>
            <template v-if="row.kind === 'work'"> · {{ row.doors }} doors · {{ row.surveys }} surveys</template>
          </span>
        </div>

        <!-- Breaks detected from the interaction gaps (same logic as the log's
             "Over by" column: gap beyond walking allowance + grace), nested
             under the app-recorded work span they occurred in. -->
        <div v-if="row.calculatedBreaks.length" class="mb-1 ml-5 flex flex-col gap-1 border-l pl-3">
          <span class="text-[10px] font-medium uppercase tracking-wide text-muted-foreground">
            Calculated breaks · {{ formatMinutesHms(row.calculatedTotalMin) }}
          </span>
          <div
            v-for="brk in row.calculatedBreaks"
            :key="brk.key"
            class="flex flex-wrap items-center gap-2 text-xs text-muted-foreground"
          >
            <CoffeeIcon class="size-3.5 text-amber-700" />
            <span>
              <span class="font-medium text-foreground">#{{ brk.rowId }}</span> ·
              <span class="font-mono">{{ brk.at }}</span>
            </span>
            <span
              class="ml-auto tabular-nums"
              :title="
                brk.gapMin != null ? `Full gap ${formatMinutesHms(brk.gapMin)} incl. allowed walking time` : undefined
              "
            >
              {{ formatMinutesHms(brk.excessMin) }}
            </span>
          </div>
        </div>
      </div>

      <p v-if="!rows.length" class="text-sm text-muted-foreground">
        No app-logged spans — the canvasser did not log a shift in the app.
      </p>
    </CardContent>
  </Card>
</template>

<script setup lang="ts">
import { ClockIcon, CoffeeIcon } from 'lucide-vue-next';

import type { ReviewLogRow, ReviewSpanKind, ReviewTimeline, ReviewTimelineSpan } from '~/client';

interface Props {
  timeline: ReviewTimeline;
  logRows: ReviewLogRow[];
  timezone: string;
}

const props = defineProps<Props>();

interface CalculatedBreak {
  key: string;
  rowId: number;
  at: string;
  excessMin: number;
  gapMin: number | null;
}

interface TimelineRow {
  key: string;
  kind: ReviewSpanKind;
  from: string;
  to: string;
  durationMin: number | null;
  doors: number | null;
  surveys: number | null;
  calculatedBreaks: CalculatedBreak[];
  calculatedTotalMin: number;
}

// Doors/surveys are counted client-side from the interaction log rows that fall
// within a work span's [start_time, end_time] window (open-ended when the span
// is still ongoing) — the review data layer doesn't pre-aggregate these per span.
function countLogRows(span: ReviewTimelineSpan): { doors: number; surveys: number } {
  const inSpan = props.logRows.filter(
    (row) => row.ts >= span.start_time && (!span.end_time || row.ts <= span.end_time)
  );
  return {
    doors: inSpan.length,
    surveys: inSpan.filter((row) => row.unified_response === 'take_survey').length,
  };
}

// Interaction-derived breaks inside a work span: a log row with
// extra_breaks_min > 0 means the gap before it exceeded the allowed walking
// time + grace. Each entry points at the interaction the break preceded —
// its # matches the interaction log table and the map pins.
function calculatedBreaksFor(span: ReviewTimelineSpan): CalculatedBreak[] {
  return props.logRows
    .filter(
      (row) =>
        row.ts >= span.start_time &&
        (!span.end_time || row.ts <= span.end_time) &&
        row.extra_breaks_min != null &&
        row.extra_breaks_min > 0
    )
    .map((row) => ({
      key: `brk-${row.id}`,
      rowId: row.id,
      at: formatDateTzToFormat(row.ts, 'hh:mm aaa', props.timezone),
      excessMin: row.extra_breaks_min as number,
      gapMin: row.gap_min ?? null,
    }));
}

const rows = computed<TimelineRow[]>(() =>
  (props.timeline.spans ?? []).map((span, index) => {
    const isOngoing = span.end_time == null;
    const durationMin = isOngoing
      ? null
      : (new Date(span.end_time as string).getTime() - new Date(span.start_time).getTime()) / 60_000;
    const counts = span.kind === 'work' ? countLogRows(span) : null;
    const calculatedBreaks = span.kind === 'work' ? calculatedBreaksFor(span) : [];
    return {
      key: `${span.start_time}-${index}`,
      kind: span.kind,
      from: formatDateTzToFormat(span.start_time, 'hh:mm aaa', props.timezone),
      to: isOngoing ? 'ongoing' : formatDateTzToFormat(span.end_time as string, 'hh:mm aaa', props.timezone),
      durationMin,
      doors: counts?.doors ?? null,
      surveys: counts?.surveys ?? null,
      calculatedBreaks,
      calculatedTotalMin: calculatedBreaks.reduce((total, brk) => total + brk.excessMin, 0),
    };
  })
);
</script>
