import { getWorkShiftReviewData, type GetWorkShiftReviewDataResponse } from '~/client';

export function useWorkShiftReviewDataQuery(workShiftId: Ref<string | undefined>, enabled?: Ref<boolean>) {
  return useQuery({
    key: () => ['workshift-review-data', workShiftId.value ?? ''],
    query: (): Promise<GetWorkShiftReviewDataResponse> =>
      getWorkShiftReviewData({
        composable: '$fetch',
        path: { work_shift_id: workShiftId.value as string },
      }),
    enabled: () => Boolean(workShiftId.value) && (enabled ? enabled.value : true),
    staleTime: 60_000,
  });
}
