<template>
  <NuxtLink :to="{ name: 'earnings-id', params: { id: earningId } }" class="flex items-center gap-2">
    <LabeledValueIcon
      :label="label || 'Earning'"
      :icon="WalletIcon"
      :loading="isLoading"
      :error="error ? 'Failed to load earning' : undefined"
    >
      <div v-if="data">
        <span class="flex gap-2 flex-wrap items-center">
          <span class="font-semibold">{{ formatAmount(data.final_total) }}</span>
          <Badge :variant="getPaymentStatusBadge(data.status).variant" size="sm">{{
            getPaymentStatusBadge(data.status).label
          }}</Badge>
        </span>
        <span class="text-sm text-muted-foreground">{{
          formatDateTzToFormat(new Date(data.created_at), 'MM/dd/yyyy, hh:mm aaa', timezone)
        }}</span>
      </div>
    </LabeledValueIcon>
  </NuxtLink>
</template>
<script setup lang="ts">
import { WalletIcon } from 'lucide-vue-next';
import LabeledValueIcon from '~/components/common/LabeledValueIcon.vue';
import { getEarningShortInfo } from '~/client';
import { formatDateTzToFormat } from '~/utils/formatDateToFormat';
import { getPaymentStatusBadge } from '~/constants/earnings/paymentStatus';

const props = defineProps<{
  label?: string;
  earningId: string;
}>();

const { data, isLoading, error } = useQuery({
  key: () => ['earning.short-info', props.earningId],
  query: () => getEarningShortInfo({ composable: '$fetch', path: { earning_id: props.earningId } }),
  enabled: () => !!props.earningId,
});

const { timezone } = useUserRole();
</script>
