import type {
  ComApiModelWorkShiftDetailsWorkShiftDetailsForCanvasser,
  ComApiModelWorkShiftDetailsWorkShiftDetailsForManager,
  WorkShiftDetailsForAdmin,
  WorkShiftDetailsForSubcontractorCanvasser,
} from '~/client';

type AnyWorkShiftDetails =
  | ComApiModelWorkShiftDetailsWorkShiftDetailsForCanvasser
  | ComApiModelWorkShiftDetailsWorkShiftDetailsForManager
  | WorkShiftDetailsForAdmin
  | WorkShiftDetailsForSubcontractorCanvasser;

export const isWorkShiftDetailsForAdminManager = (
  details: AnyWorkShiftDetails
): details is WorkShiftDetailsForAdmin | ComApiModelWorkShiftDetailsWorkShiftDetailsForManager => {
  return 'user_id' in details;
};

// Among the self-view (non-admin/manager) payloads, only the regular canvasser
// type carries pay fields. The subcontractor canvasser payload omits them, so
// `normal_pay_rate` discriminates the two.
export const isWorkShiftDetailsForCanvasser = (
  details: AnyWorkShiftDetails
): details is ComApiModelWorkShiftDetailsWorkShiftDetailsForCanvasser => {
  return !isWorkShiftDetailsForAdminManager(details) && 'normal_pay_rate' in details;
};

export const isWorkShiftDetailsForSubcontractorCanvasser = (
  details: AnyWorkShiftDetails
): details is WorkShiftDetailsForSubcontractorCanvasser => {
  return !isWorkShiftDetailsForAdminManager(details) && !('normal_pay_rate' in details);
};
