import { getWorkShiftRouteWithInteractions, type GetWorkShiftRouteWithInteractionsResponse } from '~/client';

export function useWorkShiftRouteWithInteractionsQuery(
  workShiftId: Ref<string | undefined>,
  enabled?: Ref<boolean>,
  simplified?: Ref<boolean>
) {
  return useQuery({
    key: () => ['workshift-route-with-interactions', workShiftId.value ?? '', simplified?.value ?? true],
    query: (): Promise<GetWorkShiftRouteWithInteractionsResponse> =>
      getWorkShiftRouteWithInteractions({
        composable: '$fetch',
        path: { work_shift_id: workShiftId.value as string },
        query: simplified !== undefined ? { simplified: simplified.value } : undefined,
      }),
    enabled: () => Boolean(workShiftId.value) && (enabled ? enabled.value : true),
    staleTime: 60_000,
  });
}
