<template>
  <NuxtLink :to="{ name: 'coaching-feedbacks-id', params: { id: feedbackId } }" class="flex items-center gap-2">
    <LabeledValueIcon
      :label="label || 'Coaching Feedback'"
      :icon="MessageSquareTextIcon"
      :loading="isLoading"
      :error="error ? 'Failed to load coaching feedback' : undefined"
    >
      <div v-if="data">
        <span class="flex gap-2 flex-wrap items-center">
          <Badge :variant="getFeedbackTypeBadge(data.type).variant" size="sm">{{
            getFeedbackTypeBadge(data.type).label
          }}</Badge>
          <Badge :variant="getFeedbackTriggerBadge(data.trigger).variant" size="sm">{{
            getFeedbackTriggerBadge(data.trigger).label
          }}</Badge>
        </span>
        <span class="text-sm text-muted-foreground">{{
          formatDateTzToFormat(new Date(data.created_at), 'MM/dd/yyyy, hh:mm aaa', timezone)
        }}</span>
      </div>
    </LabeledValueIcon>
  </NuxtLink>
</template>
<script setup lang="ts">
import { MessageSquareTextIcon } from 'lucide-vue-next';
import LabeledValueIcon from '~/components/common/LabeledValueIcon.vue';
import { getCoachingFeedbackShortInfo } from '~/client';
import { formatDateTzToFormat } from '~/utils/formatDateToFormat';
import { getFeedbackTypeBadge } from '~/constants/coaching-feedbacks/feedbackTypeConfig';
import { getFeedbackTriggerBadge } from '~/constants/coaching-feedbacks/feedbackTriggerConfig';

const props = defineProps<{
  label?: string;
  feedbackId: string;
}>();

const { data, isLoading, error } = useQuery({
  key: () => ['coaching-feedback.short-info', props.feedbackId],
  query: () => getCoachingFeedbackShortInfo({ composable: '$fetch', path: { feedback_id: props.feedbackId } }),
  enabled: () => !!props.feedbackId,
});

const { timezone } = useUserRole();
</script>
