<template>
  <Card>
    <CardContent class="flex flex-col gap-4">
      <div class="grid grid-cols-1 sm:grid-cols-2 gap-2 sm:gap-4">
        <LabeledEntityUser :user-id="data.user_id" />
        <LabeledEntityProject v-if="data.project_id" :project-id="data.project_id" />
        <LabeledEntityDate label="Start Time" :date="data.start_time" />
        <LabeledEntityDate v-if="data.end_time" :date="data.end_time" label="End Time" />
        <LabeledValueIcon v-else label="End Time" value="Not Finished" :icon="CalendarIcon" />
        <LabeledValueIcon
          v-if="data.net_hours != null"
          label="Net Hours"
          :value="formatHours(data.net_hours)"
          :icon="ClipboardClockIcon"
        />
        <template v-if="hasEarnings">
          <LabeledValueIcon v-if="earnedBalanceMessage && !data.earning_id" label="Earned Balance" :icon="BanknoteIcon">
            <span>
              <span class="font-medium">{{ earnedBalanceMessage.amount }}</span>
              <template v-if="earnedBalanceMessage.asOf"> as of {{ earnedBalanceMessage.asOf }}</template>
            </span>
          </LabeledValueIcon>
          <LabeledEntityEarning v-if="data.earning_id" :earning-id="data.earning_id" />
          <span v-else class="text-muted-foreground">No earning created yet for this workshift</span>
        </template>
        <LabeledEntityCoachingFeedback v-if="isAdmin && coachingFeedbackId" :feedback-id="coachingFeedbackId" />
        <LabeledEntityReport v-if="fraudReportId" :report-id="fraudReportId" />
        <LabeledValueIcon v-if="data.time_zone" label="Time Zone" :value="data.time_zone" :icon="GlobeIcon" />
      </div>
    </CardContent>
  </Card>
</template>

<script lang="ts" setup>
import type { WorkShiftDetailsForAdmin, ComApiModelWorkShiftDetailsWorkShiftDetailsForManager } from '~/client';
import type { EarnedBalanceMessage } from '~/types/workshifts/earnedBalance';
import LabeledEntityUser from '~/components/common/labeled-entity/LabeledEntityUser.vue';
import LabeledEntityProject from '~/components/common/labeled-entity/LabeledEntityProject.vue';
import LabeledEntityEarning from '~/components/common/labeled-entity/LabeledEntityEarning.vue';
import LabeledEntityCoachingFeedback from '~/components/common/labeled-entity/LabeledEntityCoachingFeedback.vue';
import LabeledEntityReport from '~/components/common/labeled-entity/LabeledEntityReport.vue';
import { formatHours } from '~/utils/formatHours';
import { BanknoteIcon, CalendarIcon, ClipboardClockIcon, GlobeIcon } from 'lucide-vue-next';

const { isAdmin } = useUserRole();

interface Props {
  data: WorkShiftDetailsForAdmin | ComApiModelWorkShiftDetailsWorkShiftDetailsForManager;
  earnedBalanceMessage: EarnedBalanceMessage | null;
}

const props = defineProps<Props>();

const coachingFeedbackId = computed(() =>
  'coaching_feedback_id' in props.data ? props.data.coaching_feedback_id : undefined
);

const fraudReportId = computed(() => props.data.fraud_report_id ?? undefined);

// Only regular canvassers have earnings and pay-rate progress. Subcontractor
// canvassers have none, so hide all earning/pay-rate UI for them.
const hasEarnings = computed(() => props.data.user_role === 'canvasser');
</script>
