// Confidence-badge display config, ported from the prototype's `confidenceConfig`
// (components/prototypes/daily-project-review/canvassingData.ts:944-949), typed
// against the generated `RiskConfidence` enum used by `ReviewFlagSection.confidence`.
export const CONFIDENCE_CONFIG: Record<RiskConfidence, { label: string; variant: BadgeVariants }> = {
  high: { label: 'High', variant: 'destructive' },
  medium: { label: 'Medium', variant: 'warning' },
  low: { label: 'Low', variant: 'info' },
};

// Unified-response display config: label + swatch hex per `UnifiedResponseTypeEnum`,
// built from `RESPONSE_TYPE_COLOR` (constants/workshifts/canvassingAppStatsConfig.ts)
// so badge/dot colors stay in lock step with the Route tab.
export interface UnifiedResponseEntry {
  label: string;
  hex: string;
}

export const UNIFIED_RESPONSE_CONFIG: Record<UnifiedResponseTypeEnum, UnifiedResponseEntry> = {
  take_survey: { label: 'Took Survey', hex: RESPONSE_TYPE_COLOR.take_survey },
  dropped_literature: { label: 'Dropped Literature', hex: RESPONSE_TYPE_COLOR.dropped_literature },
  not_home: { label: 'Not Home', hex: RESPONSE_TYPE_COLOR.not_home },
  inaccessible_address: { label: 'Inaccessible Address', hex: RESPONSE_TYPE_COLOR.inaccessible_address },
  wrong_address: { label: 'Wrong Address', hex: RESPONSE_TYPE_COLOR.wrong_address },
  refused: { label: 'Refused', hex: RESPONSE_TYPE_COLOR.refused },
  deceased: { label: 'Deceased', hex: RESPONSE_TYPE_COLOR.deceased },
  other: { label: 'Other', hex: RESPONSE_TYPE_COLOR.other },
  none: { label: 'None', hex: RESPONSE_TYPE_COLOR.none },
};

// Resolve a raw per-app response string (e.g. a `ReviewFlagRecordEnd.response`) to
// its unified display config, mirroring `getResponseColor` but returning the full
// { label, hex } pair. Returns null when there is no raw response to resolve.
export function getUnifiedResponseConfig(
  rawResponse: string | null | undefined,
  app: CanvassingApplicationName
): UnifiedResponseEntry | null {
  const unified = getUnifiedResponse(rawResponse, app);
  return unified === null ? null : UNIFIED_RESPONSE_CONFIG[unified];
}
